/* View: V_CAD_CIDADE */
CREATE VIEW V_CAD_CIDADE(
    CODCIDADE,
    NOME,
    CODPAIS,
    NOMEPAIS,
    CODUF,
    NOMEUF,
    CEP,
    USUARIO,
    DATAATU,
    HORAATU)
AS
select
c.CodCidade,
c.Nome,
c.CodPais,
p.NomePais,
c.CodUf,
u.NomeUf,
c.CEP,
c.Usuario,
c.DataAtu,
c.HoraAtu
From CAD_CIDADE c
Left Join CAD_PAIS p on p.codpais=c.codpais
Left Join CAD_UF u on u.codpais=c.codpais
  and u.coduf=c.coduf
;



/* View: V_CAD_CLAS */
CREATE VIEW V_CAD_CLAS(
    OPCCLAS,
    CODCLAS,
    DESCRCLAS,
    CODITEM,
    DESCRITEM)
AS
select
i.OpcClas,
i.CodClas,
c.Descricao as DescrClas,
i.CodItem,
i.Descricao as DescrItem
From CAD_CLASI i
Left Join CAD_CLASC c on c.opcclas=i.opcclas
   and c.codclas=i.codclas
;



/* View: V_CAD_CLIENTE */
CREATE VIEW V_CAD_CLIENTE(
    CODCLIENTE,
    NOME,
    RAZAOSOCIAL,
    TIPOCADASTRO,
    TIPOCLIENTE,
    DESCRTIPOCLIENTE,
    TIPOFISCAL,
    SEXO,
    ESTADOCIVIL,
    DATANASCFUND,
    INATIVO,
    CODREGVEN,
    NOMEREGVEN,
    CODVEND,
    NOMEVEND,
    ATACVAR,
    ENDERTPLOGRAD,
    ENDERLOGRAD,
    ENDERNUMLOGRAD,
    ENDERCOMPLEMENTO,
    ENDERBAIRRO,
    CODCIDADE,
    NOMECIDADE,
    CODPAIS,
    CODUF,
    CEP,
    DOCFISCAL,
    DOCFISCAL2,
    DOCIDENTIDADE,
    TIPOTELEFONE1,
    TIPOTELEFONE2,
    TIPOTELEFONE3,
    NUMTELEFONE1,
    NUMTELEFONE2,
    NUMTELEFONE3,
    PESSOACONTATO,
    EMAIL1,
    EMAIL2,
    NOMEPAI,
    NOMEMAE,
    NOMECONJUGE,
    NACIONALIDADE,
    FOTO,
    OBS,
    DSLOCAL,
    PROFISSAO,
    NOMEEMPPROF,
    NUMTELEFONEEMP,
    TEMPOEMP,
    GRAUESC,
    CODTIPOCLIENTE,
    USUINC,
    DATAINC,
    CODEMPINC,
    USUARIO,
    DATAATU,
    HORAATU)
AS
select
c.CodCliente,
c.Nome,
c.RazaoSocial,
c.TipoCadastro,
c.TipoCliente,
t.Descricao as DescrTipoCliente,
c.TipoFiscal,
c.Sexo,
c.EstadoCivil,
c.DataNascFund,
c.Inativo,
c.CodRegVen,
r.NomeRegVen,
c.CodVend,
v.NomeVend,
c.AtacVar,
c.EnderTpLograd,
c.EnderLograd,
c.EnderNumLograd,
c.EnderComplemento,
c.EnderBairro,
c.CodCidade,
d.Nome as NomeCidade,
d.CodPais,
d.CodUf,
d.CEP,
c.DocFiscal,
c.DocFiscal2,
c.DocIdentidade,
c.TipoTelefone1,
c.TipoTelefone2,
c.TipoTelefone3,
c.NumTelefone1,
c.NumTelefone2,
c.NumTelefone3,
c.PessoaContato,
c.Email1,
c.Email2,
c.NomePai,
c.NomeMae,
c.NomeConjuge,
c.Nacionalidade,
c.Foto,
c.Obs,
c.dslocal,
c.Profissao,
c.NomeEmpProf,
c.NumTelefoneEmp,
c.TempoEmp,
c.GrauEsc,
c.CodTipoCliente,
c.UsuInc,
c.DataInc,
c.CodEmpInc,
c.Usuario,
c.DataAtu,
c.HoraAtu
From CAD_CLIENTE c
Left Join V_CAD_CIDADE d on d.codcidade=c.codcidade
Left Join CAD_REGVEN r on r.codregven=c.codregven
Left Join CAD_VEND v on v.codvend=c.codvend
Left Join TIP_TIPOCLIENTE t on t.tpcliente=c.tipocliente
;



/* View: V_CAD_CONDPGTO */
CREATE VIEW V_CAD_CONDPGTO(
    CODCOND,
    DESCRCOND,
    ENTRADA,
    QTPARCELA,
    TPPARCELA,
    PERCDESC,
    PERCJURO,
    NUMPARC,
    QTDIAS,
    INDEFINIRFAT,
    QTREFORCO,
    USUARIO,
    DATAATU,
    HORAATU)
AS
select
m.CodCond,
mo.descricao as DescrCond,
mo.Entrada,
mo.qtparcela,
m.TpParcela,
mo.PercDesc,
mo.PercJuro,
m.NumParc,
m.QtDias,
mo.InDefinirFat,
mo.qtreforco,
m.usuario,
m.DataAtu,
m.HoraAtu 
From CAD_CONDPGTOI m
Left Join CAD_CONDPGTOC  mo on mo.codcond=m.codcond
;



/* View: V_CAD_COTACAO */
CREATE VIEW V_CAD_COTACAO(
    CODEMP,
    CODMOEDAORI,
    CODMOEDACONV,
    DATACOTACAO,
    VALOR,
    USUARIO,
    DATAATU,
    HORAATU,
    TIPOCALC,
    DSMOEDAORI,
    DSSIMBOLOORI,
    DSMOEDACONV,
    DSSIMBOLOCONV)
AS
select
m.CodEmp,
m.CodMoedaori,
m.CodMoedaconv,
m.DataCotacao,
m.Valor,
m.Usuario,
m.DataAtu,
m.HoraAtu,
m.TipoCalc,
mo.NomeMoeda as DsMoedaOri,
mo.Simbolo as DsSimboloOri,
md.NomeMoeda as DsMoedaConv,
md.Simbolo as DsSimboloConv
From CAD_COTACAO m
Left Join CAD_MOEDA mo on mo.codmoeda=m.codmoedaori
Left Join CAD_MOEDA md on md.codmoeda=m.CodMoedaconv
;



