    SIMBOLO)
AS
select
m.CodEmp,
m.CodMoeda,
m.DataCot,
m.Valor,
m.Usuario,
m.DataAtu,
m.HoraAtu,
m.TipoCalc,
mo.NomeMoeda,
mo.Simbolo
From CAD_COTMOEDA m
Left Join CAD_MOEDA mo on mo.codmoeda=m.codmoeda
;



