/* View: V_CAD_LOCALPROD */
CREATE VIEW V_CAD_LOCALPROD(
    EMPRESA,
    PRODUTO,
    DSPRODUTO,
    CODLOCAL,
    DSLOCAL)
AS
select
i.codemp,
i.codprod,
