;



/* View: V_CAD_REGCIDVEN */
CREATE VIEW V_CAD_REGCIDVEN(
    CODCIDADE,
    NOME,
    CODREGVEN,
    NOMEREGVEN,
    CODPAIS,
    NOMEPAIS,
    CODUF,
    NOMEUF,
    CEP,
    USUARIO,
    DATAATU,
    HORAATU)
AS
select
c.CodCidade,
e.Nome,
c.CodRegVen,
d.NomeRegVen,
e.CodPais,
p.NomePais,
e.CodUf,
u.NomeUf,
e.CEP,
c.Usuario,
c.DataAtu,
c.HoraAtu
From CAD_REGCIDVEND c
Left Join CAD_REGVEN d on d.codregven=c.codregven
Left Join CAD_CIDADE e on e.codcidade=c.codcidade
Left Join CAD_PAIS p   on p.codpais=e.codpais
Left Join CAD_UF u     on u.codpais=e.codpais
and u.coduf=e.coduf
;



/* View: V_CAD_REGGRUVEN */
CREATE VIEW V_CAD_REGGRUVEN(
    CODGRU,
    CODREGVEN,
    NOMEREGVEN,
    CODCIDADE,
    NOMECIDADE,
    PERCOMIS,
    CODPAIS,
    NOMEPAIS,
    CODUF,
    NOMEUF,
    CEP,
    USUARIO,
    DATAATU,
    HORAATU)
AS
select
c.codgru,
c.codregven,
d.nomeregven,
f.CodCidade,
e.Nome as nomecidade,
d.percomis,
e.CodPais,
p.NomePais,
e.CodUf,
u.NomeUf,
e.CEP,
c.Usuario,
c.DataAtu,
c.HoraAtu
From CAD_REGGRUVEND c
Left Join CAD_REGVEN d     on d.codregven=c.codregven
Left Join CAD_REGCIDVEND f on f.codregven=c.codregven
Left Join CAD_CIDADE e     on e.codcidade=f.codcidade
Left Join CAD_PAIS p       on p.codpais=e.codpais
Left Join CAD_UF u         on u.codpais=e.codpais
and u.coduf=e.coduf
;



/* View: V_FCC_LANCOR */
CREATE VIEW V_FCC_LANCOR(
    CODEMP,
    NRCTAPES,
    CODCONTA,
    DTMOV,
    NRSEQMOV,
    NRDOCUMENTO,
    SERIEDOCTO,
    CODHISTORICO,
    DESCHISTORICO,
    TPHISTORICO,
    TPDOCTO,
    DESCDOCTO,
    CODPESSOA,
    NOMEPESSOA,
    DTLIQ,
    DTCONCI,
    DTVENCTO,
    DTESTORNO,
    INESTORNO,
    TPOPERACAO,
    TPSITUACAO,
    DESCSITUACAO,
    NUMBANCO,
    NOMEBANCO,
    CODMOEDA,
    DESCMOEDA,
    SIMBOLO,
    TPCONTA,
    DSOBS,
    USUARIOCONCI,
    USUARIOESTORNO,
    USUARIO,
    DATAATU,
    HORAATU,
    VLLANCTO)
AS
select
f.CodEmp,
f.NrCtaPes,
u.CodConta,
f.dtmov,
f.nrseqmov,
f.nrdocumento,
f.seriedocto,
f.codhistorico,
j.descricao as deschistorico,
j.tphistorico,
f.tpdocto,
d.descricao as descdocto,
f.codpessoa,
m.nome as nomepessoa,
f.DtLiq,
f.dtconci,
f.dtvencto,
f.dtestorno,
f.inestorno,
f.tpoperacao,
f.tpsituacao,
CASE f.tpsituacao
WHEN 'N' then 'Normal'
WHEN 'C' then 'Conciliado'
ELSE 'Cancelado'
END as descsituacao,
u.numbanco,
s.descbanco as nomebanco,
u.codmoeda,
c.nomemoeda as DescMoeda,
c.simbolo,
u.tpconta,
f.dsObs,
f.usuarioconci,
f.usuarioestorno,
f.Usuario,
f.DataAtu,
f.HoraAtu,
cast(coalesce(f.vllancto,0) as numeric(14,2)) as vllancto
From FCC_MOV f
Left Join FCC_CONTA     u on u.nrctapes    =f.nrctapes
Left Join CAD_CLIENTE   m on m.codcliente  =f.codpessoa
Left Join FCC_HISTORICO j on j.cdhistorico =f.codhistorico
Left Join FCC_BANCO     s on s.numbanco    =u.numbanco
Left Join CAD_MOEDA     c on c.codmoeda    =u.codmoeda
Left Join TIP_DOCFIN    d on d.tpdoc       =f.tpdocto
;



/* View: V_FCC_CONTA */
CREATE VIEW V_FCC_CONTA(
    CODEMP,
    NRCTAPES,
    NUMBANCO,
    NOMEBANCO,
    CODCONTA,
    DSCONTA,
    TPCONTA,
    DSTIPOCONTA,
    INATIVO,
    PRTXJUROS,
    VLLIMITE,
    DSTITULAR,
    CODMOEDA,
    NOMEMOEDA,
    CODMODCH,
    DSMODCH,
    DTABERTURA,
    DATASALDO,
    VLCREDNORMAL,
    VLDEBNORMAL,
    VLSALDONORMAL,
    DATASALDOCONC,
    VLCREDCONC,
    VLDEBCONC,
    VLSALDOCONC,
    USUARIO,
    DATAATU,
    HORAATU)
AS
select
c.CodEmp,
c.nrctapes,
c.numbanco,
p.descbanco as NomeBanco,
c.codconta,
c.dsconta,
c.tpconta,
m.descricao as dstipoconta,
c.inativo,
c.prtxjuros,
c.vllimite,
c.dstitular,
c.codmoeda,
u.nomemoeda,
c.codmodch,
e.descricao as dsmodch,
c.dtabertura,
(select max(a.dtmov) from V_FCC_LANCOR a
where a.codemp     =c.codemp
  and a.nrctapes   =c.nrctapes
  and a.codconta   =c.codconta) as DataSaldo,
(select COALESCE(sum(COALESCE(a.vllancto,0)),0) from V_FCC_LANCOR a
where a.codemp     =c.codemp
  and a.nrctapes   =c.nrctapes
  and a.codconta   =c.codconta
  and a.tpsituacao ='N'
  and a.tphistorico='C') as VlCredNormal,
(select COALESCE(sum(COALESCE(b.vllancto,0)),0) from V_FCC_LANCOR b
where b.codemp     =c.codemp
  and b.nrctapes   =c.nrctapes
  and b.codconta   =c.codconta
  and b.tpsituacao <>'X'
  and b.tphistorico='D') as VlDebNormal,
((select COALESCE(sum(COALESCE(a1.vllancto,0)),0) from V_FCC_LANCOR a1
where a1.codemp     =c.codemp
  and a1.nrctapes   =c.nrctapes
  and a1.codconta   =c.codconta
  and a1.tpsituacao <>'X'
  and a1.tphistorico='C') -
  (select COALESCE(sum(COALESCE(b1.vllancto,0)),0) from V_FCC_LANCOR b1
   where b1.codemp     =c.codemp
     and b1.nrctapes   =c.nrctapes
     and b1.codconta   =c.codconta
     and b1.tpsituacao <>'X'
     and b1.tphistorico='D')) as VlSaldoNormal,
(select max(aa.dtmov) from V_FCC_LANCOR aa
where aa.codemp     =c.codemp
  and aa.nrctapes   =c.nrctapes
  and aa.tpsituacao ='C'
  and aa.codconta   =c.codconta) as DataSaldoConc,
(select COALESCE(sum(COALESCE(a2.vllancto,0)),0) from V_FCC_LANCOR a2
where a2.codemp     =c.codemp
  and a2.nrctapes   =c.nrctapes
  and a2.codconta   =c.codconta
  and a2.tpsituacao ='C'
  and a2.tphistorico='C') as VlCredConc,
(select COALESCE(sum(COALESCE(b2.vllancto,0)),0) from V_FCC_LANCOR b2
where b2.codemp     =c.codemp
  and b2.nrctapes   =c.nrctapes
  and b2.codconta   =c.codconta
  and b2.tpsituacao ='C'
  and b2.tphistorico='D') as VlDebConc,
((select COALESCE(sum(COALESCE(a3.vllancto,0)),0) from V_FCC_LANCOR a3
where a3.codemp     =c.codemp
  and a3.nrctapes   =c.nrctapes
  and a3.codconta   =c.codconta
  and a3.tpsituacao ='C'
  and a3.tphistorico='C') -
  (select COALESCE(sum(COALESCE(b3.vllancto,0)),0) from V_FCC_LANCOR b3
   where b3.codemp     =c.codemp
     and b3.nrctapes   =c.nrctapes
     and b3.codconta   =c.codconta
     and b3.tpsituacao ='C'
     and b3.tphistorico='D')) as VlSaldoConc,
c.Usuario,
c.DataAtu,
c.HoraAtu
From FCC_CONTA c
Left Join FCC_BANCO  p on p.numbanco=c.numbanco
Left Join CAD_MOEDA  u on u.codmoeda=c.codmoeda
Left Join TIP_CONTA  m on m.codtip  =c.tpconta
Left Join GER_MODIMP e on e.codmod  =c.codmodch
;



/* View: V_FCP_DUP */
CREATE VIEW V_FCP_DUP(
    CODEMP,
    CODFORNEC,
    NUMDUP,
    NUMPARC,
    SITUACAO,
    DATAEMISSAO,
    DATAVENCTO,
    DATAVENCTOORI,
    DATAPAG,
    PROGINCLUSAO,
    CODPORT,
    CODMOEDA,
    CODPROD,
    DESCRPROD,
    PLACAVEICULO,
    DTINISERV,
    DTFIMSERV,
    TPDOC,
    NUMDOC,
    NUMDOCAUX,
    PERCJUROMORA,
    PERCMULTA,
    OBS,
    TPINC,
    USUINC,
    USUPAG,
    USUCAN,
    DATAINC,
    DATACAN,
    DATAIMP,
    USUARIO,
    DATAATU,
    HORAATU,
    NOMEFOR,
    NOMEPORT,
    NOMEMOEDA,
    SIMBOLO,
    DESCRDOC,
    SELECAO,
    VLDUP,
    VLDUPORI,
    VLPAGO,
    VLDEDUCAO,
    VLACRESCIMO,
    VLLIQUIDO)
AS
select
f.CodEmp,
f.CodFornec,
f.NumDup,
f.NumParc,
f.Situacao,
f.DataEmissao,
f.DataVencto,
f.DataVenctoOri,
f.DataPag,
f.ProgInclusao,
f.CodPort,
f.CodMoeda,
f.CodProd,
e.desccompleta as descrprod,
e.placaveiculo,
f.DtIniServ,
f.DtFimServ,
f.TpDoc,
f.NumDoc,
f.NumDocAux,
f.PercJuroMora,
f.PercMulta,
f.Obs,
f.TpInc,
f.UsuInc,
f.UsuPag,
f.UsuCan,
f.DataInc,
f.DataCan,
f.DataImp,
f.Usuario,
f.DataAtu,
f.HoraAtu,
c.Nome as NomeFor,
p.Nome as Nomeport,
m.NomeMoeda,
m.Simbolo,
d.Descricao as DescrDoc,
'F' as Selecao,
case
    when f.codmoeda <> 3 then
       cast(f.VlDup as numeric(14,2))
    else
       cast(f.vldup as numeric(14,0))
end as vldup,
case
    when f.codmoeda <> 3 then
       cast(f.VlDupOri as numeric(14,2))
    else
       cast(f.VlDupOri as numeric(14,0))
end as VlDupOri,
case
    when f.codmoeda <> 3 then
       cast(f.VlPago as numeric(14,2))
    else
       cast(f.VlPago as numeric(14,0))
end as VlPago,
case
    when f.codmoeda <> 3 then
       cast(f.VlDeducao as numeric(14,2))
    else
       cast(f.VlDeducao as numeric(14,0))
end as VlDeducao,
case
    when f.codmoeda <> 3 then
       cast(f.VlAcrescimo as numeric(14,2))
    else
       cast(f.VlAcrescimo as numeric(14,0))
end as VlAcrescimo,
case
    when f.codmoeda <> 3 then
       cast(f.VlLiquido as numeric(14,2))
    else
       cast(f.VlLiquido as numeric(14,0))
end as VlLiquido
From FCP_DUP f
Left Join CAD_CLIENTE   c on c.codcliente=f.codfornec
Left Join FGR_PORTADOR  p on p.codport=f.codport
Left Join CAD_MOEDA     m on m.codmoeda=f.codmoeda
Left Join TIP_DOCFIN    d on d.tpdoc=f.tpdoc
Left Join PRD_PRODUTO   e on e.codprod=f.codprod
;



/* View: V_FCP_FORDUP */
CREATE VIEW V_FCP_FORDUP(
    CODEMP,
    CODCLIENTE,
    NUMDUP,
    NUMPARC,
    SITUACAO,
    DATAEMISSAO,
    DATAVENCTO,
    DATAVENCTOORI,
