    NUMDOC,
    NUMDOCAUX,
    PERCJUROMORA,
    PERCMULTA,
    OBS,
    NOME,
    DOCIDENTIDADE,
    NOMECIDADE)
AS
select
f.CodEmp,
f.CodFornec,
f.NumDup,
f.NumParc,
f.Situacao,
f.DataEmissao,
f.DataVencto,
f.DataVenctoOri,
f.DataPag,
f.ProgInclusao,
f.CodPort,
f.CodMoeda,
f.VlDup,
f.VlDupOri,
f.VlPago,
f.VlDeducao,
f.VlAcrescimo,
f.VlLiquido,
f.TpDoc,
f.NumDoc,
f.NumDocAux,
f.PercJuroMora,
