Left Join CAD_CIDADE    e on e.codcidade=c.codcidade
Left Join FGR_PORTADOR  p on p.codport=f.codport
Left Join CAD_MOEDA     m on m.codmoeda=f.codmoeda
Left Join TIP_DOCFIN    d on d.tpdoc=f.tpdoc
;



/* View: V_FCP_PAG */
CREATE VIEW V_FCP_PAG(
    CODEMPDUP,
    CODFORNEC,
    NUMDUP,
    NUMPARC,
    CODEMPCX,
    CODTERM,
    DATAABERT,
    NUMSEQCX,
    NUMSEQITEM,
    CODMOEDA,
    USUARIO,
    DATAATU,
    HORAATU,
    DATALANCTO,
    TPDOC,
    CODHIST,
    VLDOC,
    VLCONTADO,
    VLDIFERENCA,
    CODPORT,
    NUMDOC,
    NUMDOCAUX,
    NOMEMOEDA,
    DESCRDOC,
    DESCRHIST,
    DATAEMISSAO,
    DATAVENCTO,
    VLDUP,
    VLPAGO,
    VLDEDUCAO,
    VLACRESCIMO,
    VLLIQUIDO,
    NOMEFOR,
    SELECAO)
AS
select
p.CodEmpDup,
p.CodFornec,
p.NumDup,
p.NumParc,
p.CodEmpCx,
p.CodTerm,
p.DataAbert,
p.NumSeqCx,
p.NumSeqItem,
f.codmoeda,
p.Usuario,
p.DataAtu,
p.HoraAtu,
c.DataLancto,
c.TpDoc,
c.CodHist,
c.VlDoc,
c.VlContado,
c.VlDiferenca,
c.CodPort,
c.NumDoc,
c.NumDocAux,
j.nomemoeda,
d.descricao as descrdoc,
h.descricao as descrhist,
f.dataemissao,
f.datavencto,
f.vldup,
f.vlpago,
f.vldeducao,
f.vlacrescimo,
f.vlliquido,
f.Nomefor,
'F' as Selecao
From FCP_PAG p
Left Join FCX_CAIXAI c on c.codemp    =p.codempcx
                      and c.codterm   =p.codterm
                      and c.dataabert =p.dataabert
                      and c.numseqcx  =p.numseqcx
                      and c.numseqitem=p.numseqitem
Left Join TIP_DOCFIN d on d.tpdoc     =c.tpdoc
Left Join FCX_HIST   h on h.codhist   =c.codhist
Left Join V_FCP_DUP  f on f.codemp    =p.codempdup
                      and f.codfornec =p.codfornec
                      and f.numdup    =p.numdup
                      and f.numparc   =p.numparc
Left Join CAD_MOEDA  j on j.codmoeda  =f.codmoeda
;



/* View: V_FCR_CHEQUE */
CREATE VIEW V_FCR_CHEQUE(
    CODEMP,
    CODCLIENTE,
    NUMCHEQUE,
    NUMBANCO,
    NOMEBANCO,
    CODEMITENTE,
    SITUACAO,
    DATAEMISSAO,
    DATAVENCTO,
