    VLDEDUCAO,
    VLACRESCIMO,
    VLLIQUIDO,
    PERCJUROMORA,
    PERCMULTA,
    NUMDOCFISCAL,
    OBS,
    USUINC,
    USUREC,
    USUCAN,
    DATAINC,
    DATACAN,
    DATAIMP,
    USUARIO,
    DATAATU,
    HORAATU,
    NOMECLI,
    RAZAOSOCIAL,
    DOCTOCLI,
    ENDERECOCLI,
    CIDADECLI,
    NOMEEMITENTE,
    CODPAIS,
    NOMEMOEDA,
    SIMBOLO,
    SELECAO)
AS
select
f.CodEmp,
f.CodCliente,
f.Numcheque,
f.NumBanco,
j.descbanco as NomeBanco,
f.CodEmitente,
f.Situacao,
f.DataEmissao,
f.DataVencto,
f.DataVenctoOri,
f.DataRec,
g.CodGruRegVen,
f.CodMoeda,
f.Vlcheque,
f.VlchequeOri,
f.VlRecebido,
f.VlDeducao,
f.VlAcrescimo,
f.VlLiquido,
f.PercJuroMora,
f.PercMulta,
c.DocFiscal as NumDocFiscal,
f.Obs,
f.UsuInc,
f.UsuRec,
f.UsuCan,
f.DataInc,
f.DataCan,
f.DataImp,
f.Usuario,
f.DataAtu,
f.HoraAtu,
c.Nome as Nomecli,
c.RazaoSocial,
CASE WHEN c.tipofiscal = 'F' THEN c.DocIdentidade
ELSE
c.docfiscal
END AS DoctoCli,
c.enderlograd as enderecoCli,
e.nome as CidadeCli,
d.nome as NomeEmitente,
e.codpais,
m.NomeMoeda,
m.Simbolo,
'F' as selecao
From FCR_CHEQUEPRE f
Left Join CAD_CLIENTE   c on c.codcliente=f.codcliente
Left Join CAD_CLIENTE   d on d.codcliente=f.codemitente
Left Join CAD_VEND      g on g.codvend=c.codvend
Left Join CAD_MOEDA     m on m.codmoeda=f.codmoeda
Left Join FCC_BANCO     j on j.numbanco=f.numbanco
Left Join V_CAD_CIDADE  e on e.codcidade=c.codcidade
;



