    USUCAN,
    DATAINC,
    DATACAN,
    DATAIMP,
    USUARIO,
    DATAATU,
    HORAATU,
    NOME,
    DOCIDENTIDADE,
    NOMECIDADE,
    PAIS,
    NUMDOCFISCAL,
    CODREGVEN,
    NOMEPORT,
    NOMEMOEDA,
    SIMBOLO,
    DESCRDOC,
    CODVEND,
    DESCRVEND)
AS
select
f.CodEmp,
f.CodCliente,
f.NumFat,
f.NumParc,
f.Situacao,
f.DataEmissao,
f.DataVencto,
f.DataVenctoOri,
f.DataRec,
f.ProgInclusao,
f.CodPort,
f.CodMoeda,
f.VlFatura,
f.VlFatOri,
f.VlRecebido,
f.VlDeducao,
f.VlAcrescimo,
f.VlFatura-f.vlRecebido as vlLiquido,
f.TpDoc,
f.NumDoc,
f.NumDocAux,
f.PercJuroMora,
f.PercMulta,
f.Obs,
f.TpInc,
f.UsuInc,
f.UsuRec,
f.UsuCan,
f.DataInc,
f.DataCan,
f.DataImp,
f.Usuario,
f.DataAtu,
f.HoraAtu,
c.Nome,
c.DocIdentidade,
e.nome as nomeCidade,
i.nomepais as pais,
c.docfiscal as NumDocFiscal,
c.codregven,
p.Nome as Nomeport,
m.NomeMoeda,
m.Simbolo,
d.Descricao as DescrDoc,
f.codvend,
j.nomevend  as DescrVend
From FCR_FAT f
Left Join CAD_CLIENTE   c on c.codcliente=f.codcliente
Left Join CAD_CIDADE    h on h.codcidade=c.codcidade
Left Join CAD_PAIS      i on i.codpais=h.codpais
Left Join FGR_PORTADOR  p on p.codport=f.codport
Left Join CAD_MOEDA     m on m.codmoeda=f.codmoeda
Left Join TIP_DOCFIN    d on d.tpdoc=f.tpdoc
Left Join CAD_CIDADE    e on e.codcidade=c.codcidade
Left Join CAD_VEND      j on j.codvend=f.codvend
;



/* View: V_FCR_FAT */
CREATE VIEW V_FCR_FAT(
    CODEMP,
    CODCLIENTE,
    NUMFAT,
    NUMPARC,
    SITUACAO,
    TPPARCELA,
    DATAEMISSAO,
    DATAVENCTO,
    DATAVENCTOORI,
    DATAREC,
    CODGRUREGVEN,
    PROGINCLUSAO,
    CODPORT,
    CODMOEDA,
    NUMPARCORI,
    TPDOC,
    NUMDOC,
    NUMDOCAUX,
    NUMDOCFISCAL,
    PRJUROS,
    PERCMULTA,
    NUMNOTA,
    NUMRES,
    DATARES,
    NUMMOV,
    DATAMOV,
    DTINICONTRATO,
    DTFIMCONTRATO,
    CODIMOVEL,
    DESCIMOVEL,
    OBS,
    TPINC,
    USUINC,
    USUREC,
    USUCAN,
    DATAINC,
    DATACAN,
    DATAIMP,
    USUARIO,
    DATAATU,
    HORAATU,
    NOMECLI,
    RAZAOSOCIAL,
    DOCTOCLI,
    ENDERECOCLI,
    NUMTELEFONE1,
    NUMTELEFONE2,
    NUMTELEFONE3,
    CIDADECLI,
    CODPAIS,
    NOMEPAIS,
    NOMEPORT,
    NOMEMOEDA,
    SIMBOLO,
    DESCRDOC,
    CODVEND,
    DESCRVEND,
    SELECAO,
    VLTOTRECEBIDO,
    VLENTRADA,
    VLFATURA,
    VLFATORI,
    VLRECEBIDO,
    VLDEDUCAO,
    VLACRESCIMO,
    VLLIQUIDO)
AS
select
f.CodEmp,
f.CodCliente,
f.NumFat,
f.NumParc,
f.Situacao,
CASE 
   WHEN f.tpparcela = 'R' then 'Reforco'
   WHEN f.numparc  >= 200   then 'Parcial'
   ELSE 'Normal'
END as tpparcela,
f.DataEmissao,
f.DataVencto,
f.DataVenctoOri,
f.DataRec,
g.CodGruRegVen,
f.ProgInclusao,
f.CodPort,
f.CodMoeda,
f.NumParcOri,
f.TpDoc,
f.NumDoc,
f.NumDocAux,
c.DocFiscal as NumDocFiscal,
c.PrJuros,
f.PercMulta,
f.numnota,
j.numres,
j.datares,
f.nummov,
f.datamov,
f.dtIniContrato,
f.dtFimContrato,
f.codImovel,
i.desccompleta as descImovel,
f.Obs,
f.TpInc,
f.UsuInc,
f.UsuRec,
f.UsuCan,
f.DataInc,
f.DataCan,
f.DataImp,
f.Usuario,
f.DataAtu,
f.HoraAtu,
c.Nome as Nomecli,
c.RazaoSocial,
CASE c.tipofiscal
WHEN 'F' THEN c.DocIdentidade
ELSE c.docfiscal
END AS DoctoCli,
c.enderlograd as enderecoCli,
c.numtelefone1,
c.numtelefone2,
c.numtelefone3,
e.nome as CidadeCli,
e.codpais,
e.nomepais,
p.Nome as Nomeport,
m.NomeMoeda,
m.Simbolo,
d.Descricao as DescrDoc,
f.codvend,
g.nomevend as descrVend,
'F' as selecao,
case
   when f.codmoeda <> 3 then
       cast(coalesce(f.VlTotRecebido,0) as numeric(16,2))
   else
       cast(coalesce(f.VlTotRecebido,0) as numeric(16,0))
end as VlTotRecebido,
case
   when f.codmoeda <> 3 then
       cast(COALESCE(f.vlentrada,0) as numeric(16,2))
   else
       cast(COALESCE(f.vlentrada,0) as numeric(16,0))
end as VlEntrada,
case
   when f.codmoeda <> 3 then
       cast(coalesce(f.vlfatura,0) as numeric(16,2))
   else
       cast(coalesce(f.vlfatura,0) as numeric(16,0))
end as vlfatura,
case
   when f.codmoeda <> 3 then
       cast(coalesce(f.VlFatOri,0) as numeric(16,2))
   else
       cast(coalesce(f.VlFatOri,0) as numeric(16,0))
end as VlFatOri,
case
   when f.codmoeda <> 3 then
       cast(coalesce(f.vlrecebido,0) as numeric(16,2))
   else
       cast(coalesce(f.vlrecebido,0) as numeric(16,0))
end as vlrecebido,
case
   when f.codmoeda <> 3 then
       cast(coalesce(f.vldeducao,0) as numeric(16,2))
   else
       cast(coalesce(f.vldeducao,0) as numeric(16,0))
end as vldeducao,
case
   when f.codmoeda <> 3 then
       cast(coalesce(f.vlacrescimo,0) as numeric(16,2))
   else
       cast(coalesce(f.vlacrescimo,0) as numeric(16,0))
end as vlacrescimo,
case
   when f.codmoeda <> 3 then
       cast(COALESCE((f.VlFatura-f.vlRecebido),0) as numeric(16,2))
   else
       cast(COALESCE((f.VlFatura-f.vlRecebido),0) as numeric(16,0))
end as vlliquido
From FCR_FAT f
Left Join CAD_CLIENTE   c on c.codcliente=f.codcliente
Left Join PRD_PRODUTO   i on i.codprod=f.codimovel
Left Join FGR_PORTADOR  p on p.codport=f.codport
Left Join CAD_MOEDA     m on m.codmoeda=f.codmoeda
Left Join TIP_DOCFIN    d on d.tpdoc=f.tpdoc
Left Join V_CAD_CIDADE  e on e.codcidade=c.codcidade
Left Join CAD_VEND      g on g.codvend=f.codvend
Left Join MOV_MOVRES    j on j.codemp=f.codemp
                        and  j.datamov=f.datamov
                        and  j.nummov=f.nummov
;



/* View: V_FCR_FATCLI */
CREATE VIEW V_FCR_FATCLI(
    CODEMP,
    CODCLIENTE,
    NUMFAT,
    NUMPARC,
    SITUACAO,
    DATAEMISSAO,
    DATAVENCTO,
    DATAVENCTOORI,
    DATAREC,
    CODGRUREGVEN,
    PROGINCLUSAO,
    CODPORT,
    CODMOEDA,
    TPDOC,
    NUMDOC,
    NUMDOCAUX,
    NUMDOCFISCAL,
    PERCJUROMORA,
    PERCMULTA,
    TPPARCELA,
    NUMNOTA,
    NUMRES,
    DATARES,
    NUMMOV,
    DATAMOV,
    OBS,
    TPINC,
    USUINC,
    USUREC,
    USUCAN,
    DATAINC,
    DATACAN,
    DATAIMP,
    USUARIO,
    DATAATU,
    HORAATU,
    NUMPARCORI,
    NOMECLI,
    RAZAOSOCIAL,
    ENDERECOCLI,
    CIDADECLI,
    CODPAIS,
    NOMEPAIS,
    NOMEPORT,
    NOMEMOEDA,
    SIMBOLO,
    DESCRDOC,
    CODVEND,
    DESCRVEND,
    DOCFISCAL,
    SELECAO,
    VLTOTRECEBIDO,
    VLENTRADA,
    VLFATURA,
    VLFATORI,
    VLRECEBIDO,
    VLDEDUCAO,
    VLACRESCIMO,
    VLLIQUIDO)
AS
select
f.CodEmp,
f.CodCliente,
f.NumFat,
f.NumParc,
f.Situacao,
f.DataEmissao,
f.DataVencto,
f.DataVenctoOri,
f.DataRec,
g.CodGruRegVen,
f.ProgInclusao,
f.CodPort,
f.CodMoeda,
f.TpDoc,
f.NumDoc,
f.NumDocAux,
c.DocFiscal as NumDocFiscal,
f.PercJuroMora,
f.PercMulta,
f.tpparcela,
f.numnota,
j.numres,
j.datares,
f.nummov,
f.datamov,
f.Obs,
f.TpInc,
f.UsuInc,
f.UsuRec,
f.UsuCan,
f.DataInc,
f.DataCan,
f.DataImp,
f.Usuario,
f.DataAtu,
f.HoraAtu,
f.numparcori,
c.Nome as Nomecli,
c.razaosocial,
c.enderlograd as enderecoCli,
e.nome as CidadeCli,
e.codpais,
e.nomepais,
p.Nome as Nomeport,
m.NomeMoeda,
m.Simbolo,
d.Descricao as DescrDoc,
f.codvend,
g.nomevend as descrVend,
c.docfiscal,
'F' as selecao,
Sum(COALESCE(f.VlTotRecebido,0)) as VlTotRecebido,
Sum(COALESCE(f.VlEntrada,0))   as VlEntrada,
Sum(COALESCE(f.VlFatura,0))    as VlFatura,
Sum(COALESCE(f.VlFatOri,0))    as VlFatOri,
Sum(COALESCE(f.VlRecebido,0))  as VlRecebido,
Sum(COALESCE(f.VlDeducao,0))   as VlDeducao,
Sum(COALESCE(f.VlAcrescimo,0)) as VlAcrescimo,
Sum(COALESCE(f.VlLiquido,0))   as VlLiquido
From FCR_FAT f
Left Join CAD_CLIENTE   c on c.codcliente=f.codcliente
Left Join FGR_PORTADOR  p on p.codport=f.codport
Left Join CAD_MOEDA     m on m.codmoeda=f.codmoeda
Left Join TIP_DOCFIN    d on d.tpdoc=f.tpdoc
Left Join V_CAD_CIDADE  e on e.codcidade=c.codcidade
Left Join CAD_VEND      g on g.codvend=f.codvend
Left Join MOV_MOVRES    j on j.codemp=f.codemp
                        and  j.datamov=f.datamov
                        and  j.nummov=f.nummov
group by f.CodEmp,f.CodCliente,f.NumFat,f.NumParc,f.Situacao,f.DataEmissao,
f.DataVencto,f.DataVenctoOri,f.DataRec,g.CodGruRegVen,f.ProgInclusao,f.CodPort,
f.CodMoeda,f.TpDoc,f.NumDoc,f.NumDocAux,c.DocFiscal,f.PercJuroMora,
f.PercMulta,f.tpparcela,f.numnota,j.numres,j.datares,f.nummov,f.datamov,f.Obs,f.TpInc,f.UsuInc,
f.UsuRec,f.UsuCan,f.DataInc,f.DataCan,f.DataImp,f.Usuario,f.DataAtu,f.HoraAtu,f.numparcori,c.Nome,
c.razaosocial,c.enderlograd,e.nome,e.codpais,e.nomepais,p.Nome,m.NomeMoeda,m.Simbolo,
d.Descricao,f.codvend,g.nomevend,c.docfiscal
;



