/* View: V_FCX_CAIXAC */
CREATE VIEW V_FCX_CAIXAC(
    CODEMP,
    CODTERM,
    DATAABERT,
    NUMSEQCX,
    USUCX,
    USUCONF,
    INFECHADO,
    DATAFECHAMENTO,
    OBSFECHAMENTO,
    INDIFERENCA,
