Left Join ADM_USUARIO s on s.codusu=f.usuconf
;



/* View: V_FCX_CAIXAI */
CREATE VIEW V_FCX_CAIXAI(
    CODEMP,
    CODTERM,
    DATAABERT,
    NUMSEQCX,
    NUMSEQITEM,
    DATALANCTO,
    TPDOC,
    CODHIST,
    VLDOC,
    VLCONTADO,
    VLDIFERENCA,
    CODPORT,
    NUMDOC,
    NUMDOCAUX,
    DATAVENCTO,
    OBS,
    USUARIO,
    DATAATU,
    HORAATU,
    TIPOHIST,
    CODPROD,
    CODCOR,
    DSCHASSI,
    ANOFABR,
    TPVEICULO,
    ANOMODELO,
    TPCOMBUSTIVEL,
    PLACAVEICULO,
    KMATUAL,
    KMFINAL,
    DATATROCA,
    DESCRPROD,
    DESCRDOC,
    DESCRHIST,
    OPER,
    MOEDAORIGEM,
    CODMOEDA,
    NOMEMOEDA,
    SIMBOLO,
    TIPOCALC,
    VLCOT)
AS
select
f.CodEmp,
f.CodTerm,
f.DataAbert,
f.NumSeqCx,
f.NumSeqItem,
f.DataLancto,
f.TpDoc,
f.CodHist,
f.VlDoc,
f.VlContado,
f.VlDiferenca,
f.CodPort,
f.NumDoc,
f.NumDocAux,
f.DataVencto,
f.Obs,
f.Usuario,
f.DataAtu,
f.HoraAtu,
h.tipohist,
f.codprod,
j.codcor,
j.dschassi,
j.anofabr,
j.tpveiculo,
j.anomodelo,
j.tpcombustivel,
j.placaveiculo,
j.kmatual,
j.kmfinal,
j.datatroca,
j.desccompleta as descrprod,
d.Descricao as descrdoc,
h.Descricao as descrhist,
h.Oper,
a.codmoeda as moedaorigem,
r.codmoeda,
m.nomemoeda,
m.simbolo,
c.tipocalc,
c.valor as vlcot
From FCX_CAIXAI f
Left Join ADM_PARAM  a   on a.codemp  =f.codemp
Left Join TIP_DOCFIN d   on d.tpdoc   =f.tpdoc
Left Join FCX_HIST h     on h.codhist =f.codhist
Left Join FGR_DOCREL r   on r.codemp  =f.codemp
                        and r.tpdoc   =f.tpdoc
Left Join CAD_MOEDA m    on m.codmoeda=r.codmoeda
Left Join CAD_COTMOEDA c on c.codemp  =f.codemp
                        and c.codmoeda=r.codmoeda
                        and c.datacot =f.datalancto
Left Join PRD_PRODUTO j  on j.codprod =f.codprod
;



/* View: V_FCX_CAIXADOC */
CREATE VIEW V_FCX_CAIXADOC(
    CODEMP,
    CODTERM,
    DATAABERT,
    NUMSEQCX,
    TPDOC,
    DESCRDOC,
    VLDOCCRED,
    VLDOCDEB,
    VLDOCSALDO)
AS
select
c1.CodEmp,
c1.CodTerm,
c1.DataAbert,
c1.NumSeqCx,
c1.TpDoc,
c1.descrdoc,
(select COALESCE(sum(COALESCE(c2.vldoc,0)),0) from V_FCX_CAIXAI c2
where c2.codemp=c1.codemp
  and c2.codterm=c1.codterm
  and c2.dataabert=c1.dataabert
  and c2.numseqcx=c1.numseqcx
  and c2.tpdoc=c1.tpdoc
  and c2.oper='C') as VlDocCred,
(select COALESCE(sum(COALESCE(c3.vldoc,0)),0) from V_FCX_CAIXAI c3
where c3.codemp=c1.codemp
  and c3.codterm=c1.codterm
  and c3.dataabert=c1.dataabert
  and c3.numseqcx=c1.numseqcx
  and c3.tpdoc=c1.tpdoc
  and c3.oper='D') as VlDocDeb,
((select COALESCE(sum(COALESCE(c4.vldoc,0)),0) from V_FCX_CAIXAI c4
 where c4.codemp=c1.codemp
  and c4.codterm=c1.codterm
  and c4.dataabert=c1.dataabert
  and c4.numseqcx=c1.numseqcx
  and c4.tpdoc=c1.tpdoc
  and c4.oper='C') - 
 (select COALESCE(sum(COALESCE(c5.vldoc,0)),0) from V_FCX_CAIXAI c5
 where c5.codemp=c1.codemp
  and c5.codterm=c1.codterm
  and c5.dataabert=c1.dataabert
  and c5.numseqcx=c1.numseqcx
  and c5.tpdoc=c1.tpdoc
  and c5.oper='D')) as VlDocSaldo
From V_FCX_CAIXAI c1
 Group By codemp, codterm, dataabert, numseqcx, tpdoc, descrdoc
;



/* View: V_FCX_CAIXAF */
CREATE VIEW V_FCX_CAIXAF(
    CODEMP,
    CODTERM,
    DATAABERT,
    NUMSEQCX,
    TPDOC,
    VLDOC,
    VLCONTADO,
    VLDIFERENCA,
    CODMOEDA,
    OBS,
    DESCRDOC)
AS
select
f.CodEmp,
f.CodTerm,
f.DataAbert,
f.NumSeqCx,
f.TpDoc,
f.VlDoc,
f.VlContado,
f.VlDiferenca,
c.codmoeda,
f.Obs,
d.Descricao as descrdoc
From FCX_CAIXAF f
Left Join TIP_DOCFIN d on d.tpdoc=f.tpdoc
Left Join FGR_DOCREL c on c.codemp=f.codemp
                      and c.tpdoc =f.tpdoc
;



/* View: V_FCX_CAIXARES */
CREATE VIEW V_FCX_CAIXARES(
    CODEMP,
    CODTERM,
    DATAABERT,
    NUMSEQCX,
    TPDOC,
    CODHIST,
    DESCRDOC,
    DESCRHIST,
    CODMOEDA,
    SIMBOLO,
    TIPOCALC,
    VLCOT,
    VLDOCCRED,
    VLDOCDEB,
    VLDOCSALDO)
AS
select
c1.CodEmp,
c1.CodTerm,
c1.DataAbert,
c1.NumSeqCx,
c1.TpDoc,
c1.CodHist,
c1.descrdoc,
c1.descrhist,
c1.codmoeda,
c1.simbolo,
c1.tipocalc,
c1.vlcot,
(select COALESCE(sum(COALESCE(c2.vldoc,0)),0) from V_FCX_CAIXAI c2
where c2.codemp=c1.codemp
  and c2.codterm=c1.codterm
  and c2.dataabert=c1.dataabert
  and c2.numseqcx=c1.numseqcx
  and c2.tpdoc=c1.tpdoc
  and c2.oper='C'
  and c2.codhist=c1.codhist) as VlDocCred,
(select COALESCE(sum(COALESCE(c3.vldoc,0)),0) from V_FCX_CAIXAI c3
where c3.codemp=c1.codemp
  and c3.codterm=c1.codterm
  and c3.dataabert=c1.dataabert
  and c3.numseqcx=c1.numseqcx
  and c3.tpdoc=c1.tpdoc
  and c3.oper='D'
  and c3.codhist=c1.codhist) as VlDocDeb,
((select COALESCE(sum(COALESCE(c4.vldoc,0)),0) from V_FCX_CAIXAI c4
 where c4.codemp=c1.codemp
  and c4.codterm=c1.codterm
  and c4.dataabert=c1.dataabert
  and c4.numseqcx=c1.numseqcx
  and c4.tpdoc=c1.tpdoc
  and c4.oper='C'
  and c4.codhist=c1.codhist) - 
 (select COALESCE(sum(COALESCE(c5.vldoc,0)),0) from V_FCX_CAIXAI c5
 where c5.codemp=c1.codemp
  and c5.codterm=c1.codterm
  and c5.dataabert=c1.dataabert
  and c5.numseqcx=c1.numseqcx
  and c5.tpdoc=c1.tpdoc
  and c5.oper='D'
  and c5.codhist=c1.codhist)) as VlDocSaldo
From V_FCX_CAIXAI c1
 Group By codemp, codterm, dataabert, numseqcx, tpdoc, codhist,
   descrdoc, descrhist, codmoeda, simbolo, tipocalc, vlcot
;



/* View: V_FCX_DRE */
CREATE VIEW V_FCX_DRE(
    CODEMP,
    CODDRE,
    ANOEXERCICIO,
    NUMSEQ,
    CODHIST,
    CODCONTA,
    DESCRCONTA,
    DESCRHIST,
    USUARIO,
    DATAATU,
    HORAATU,
    SELECAO)
AS
select
e.codemp,
e.coddre,
e.anoexercicio,
e.numseq,
e.codhist,
e.codconta,
e.descrConta,
d.descricao as descrHist,
e.usuario,
e.dataatu,
e.horaatu,
'F' as Selecao
From FCX_DRE E
left Join FCX_HIST D on d.codhist=e.codhist
;



/* View: V_FIS_NFC */
CREATE VIEW V_FIS_NFC(
    CODEMPNF,
    DATASEQNF,
    NUMSEQNF,
    DATAEMI,
    NUMNF,
    TIPONF,
    DSSERIE,
    CONDMOV,
    DSCONDMOV,
    NUMMOV,
    DATAMOV,
    CODCLIENTE,
    NOMECLIFOR,
    RAZAOSOCIAL,
    NUMTELEFONE1,
    NUMTELEFONE2,
    NUMTELEFONE3,
    ENDERECOCLI,
    CODCIDADE,
    CIDADECLI,
    PAISCLI,
    DOCCLIFOR,
    DOCFISCAL,
    FONECLIFOR,
    CODOPER,
    SITUACAO,
    CODMOEDA,
    DESCRVENCTO,
    OBS,
    TPINC,
    USUINC,
    DATAINC,
    USUARIO,
    DATAATU,
    HORAATU,
    DESCROPER,
    NOMEMOEDA,
    SIMBOLO,
    NUMTIMBRADO,
    NUMCOMP,
    SELECAO,
    VLTOTIVA10,
    VLTOTIVA05,
    VLTOTISENTO,
    VLTOTDESCTO,
    VLIVA10,
    VLIVA05,
    VLTOTNOTA,
    VLTOTGRAVADO,
    VLTOTIMPOSTO)
AS
select 
n.CodEmpNf,
n.dataseqnf,
n.numseqnf,
n.dataemi,
n.numnf,
n.TipoNf,
n.dsserie,
n.CondMov,
case n.condmov
    when 'V' then 'FACTURA CONTADO'
    else 'ACTURA CREDITO'
end as dscondmov,
(select First 1 a.NumMov from MOV_MOVNFS a
        where a.codempnf  =n.codempnf
          and a.dataemi   =n.dataemi
          and a.numnf     =n.numnf)
as NumMov,
(select First 1 b.DataMov from MOV_MOVNFS b
        where b.codempnf  =n.codempnf
          and b.dataemi   =n.dataemi
          and b.numnf     =n.numnf)
as DataMov,
n.CodCliente,
p.Nome as NomeCliFor,
P.RazaoSocial,
P.NumTelefone1,
P.NumTelefone2,
P.NumTelefone3,
p.enderlograd as enderecocli,
n.CodCidade,
q.nome as cidadecli,
p.nacionalidade as paiscli,
n.DocCliFor,
p.DocFiscal,
p.numtelefone1 as foneclifor,
n.CodOper,
n.Situacao,
n.CodMoeda,
n.DescrVencto,
n.Obs,
n.TpInc,
n.UsuInc,
n.DataInc,
n.Usuario,
n.DataAtu,
n.HoraAtu,
o.Descricao as DescrOper,
mo.NomeMoeda,
mo.Simbolo,
n.numtimbrado,
(n.DsSerie ||'-'|| lpad(n.numnf, 7, '0')) as NumComp,
'F' as selecao,
COALESCE(cast(n.vltotiva10 as numeric(16,2)),0)  as vltotiva10,
COALESCE(cast(n.vltotiva05 as numeric(16,2)),0)  as vltotiva05,
COALESCE(cast(n.vltotisento as numeric(16,2)),0) as vltotisento,
COALESCE(cast(n.vltotdescto as numeric(16,2)),0) as vltotdescto,
COALESCE(cast(n.vliva10 as numeric(16,2)),0)     as vliva10,
COALESCE(cast(n.vliva05 as numeric(16,2)),0)     as vliva05,
COALESCE(cast(n.vltotnota as numeric(16,2)),0)   as vltotnota,
COALESCE(cast(n.vltotiva10 as numeric(14,2)),0)+COALESCE(cast(n.vltotiva05 as numeric(14,2)),0) as vltotgravado,
COALESCE(cast(n.vliva10 as numeric(14,2)),0)+COALESCE(cast(n.vliva05 as numeric(14,2)),0) as vltotImposto
From FIS_NFC n
Left Join CAD_CLIENTE   p on p.codcliente=n.codcliente
Left Join CAD_CIDADE    q on q.codcidade =n.codcidade
Left Join MOV_OPER      o on o.codoper   =n.codoper
Left Join CAD_MOEDA    mo on mo.codmoeda =n.codmoeda
Left Join MOV_MOVNFS    r on r.codempnf  =n.codempnf
                         and r.dataemi   =n.dataemi
                         and r.numnf     =n.numnf
;



/* View: V_FIS_NFI */
CREATE VIEW V_FIS_NFI(
    CODEMPNF,
    DATASEQNF,
    NUMSEQNF,
    DATAEMI,
    NUMNF,
    TIPONF,
    NUMITEM,
    CODPROD,
    QTNF,
    DESCRPROD,
    DESCCOMPLETA,
    CODBAR,
    DSCHASSI,
    DSMOTOR,
    CODMARCA,
    DSMARCA,
    CODMODELO,
    DSMODELO,
    ANOFABR,
    ANOMODELO,
    CODCOR,
    DSCOR,
    TPCOMBUSTIVEL,
    INNOVOUSADO,
    DSTIPOCOMBUSTIVEL,
    PLACAVEICULO,
    TPVEICULO,
    SITUACAO,
    VLUNITNF,
    VLTOTNF,
    VLTOTIVA10,
    VLTOTIVA05,
    VLTOTISENTO,
    VLTOTNF2,
    VLTOTNF3,
    VLTOTNF4,
    PERDESC,
    VLTOTDESC,
    PRIMPOSTO,
    USUARIO,
    DATAATU,
    HORAATU)
AS
select
i.CodEmpNf,
i.dataseqnf,
i.numseqnf,
i.DataEmi,
i.NumNf,
i.TipoNf,
i.NumItem,
i.CodProd,
i.QtNf,
p.descricao as descrProd,
p.desccompleta,
P.codbar,
P.dschassi,
P.dsmotor,
P.codmarca,
c.descricao as dsmarca,
p.codmodelo,
d.descricao as dsmodelo,
p.anofabr,
p.anomodelo,
p.codcor,
e.descricao as dscor,
p.tpcombustivel,
p.innovousado,
f.descricao as dstipocombustivel,
p.placaveiculo,
p.tpveiculo,
i.situacao,
COALESCE(cast(i.VlUnitNf as numeric(16,2)),0) as VlUnitNf,
COALESCE(cast(i.VlTotNf as numeric(16,2)),0) as VlTotNf,
(case when (p.imposto = 10) then COALESCE(cast(i.VlTotNf as numeric(16,2)),0) else 0 end) as VlTotIva10,
(case when (p.imposto = 5)  then COALESCE(cast(i.VlTotNf as numeric(16,2)),0) else 0 end) as VLTotIva05,
(case when (p.imposto = 0 or p.Imposto is null) then COALESCE(cast(i.VlTotNf as numeric(16,2)),0) else 0 end) as VlTotIsento,
(case when (p.Imposto = 0 or p.Imposto is null) then i.VlTotNf else 0 end) as VlTotNf2,
(case when p.Imposto =  5 then i.VlTotNf else 0 end) as VlTotNf3,
(case when p.Imposto = 10 then i.VlTotNf else 0 end) as VlTotNf4,
COALESCE(cast(i.PerDesc as numeric(6,2)),0) as PerDesc,
COALESCE(cast(i.VlTotDesc as numeric(6,2)),0) as VlTotDesc,
COALESCE(cast(p.Imposto as numeric(6,2)),0) as primposto,
i.Usuario,
i.DataAtu,
i.HoraAtu
From FIS_NFI i
Left Join PRD_PRODUTO     p on p.codprod      =i.codprod
Left Join PRD_MARCA       c on c.codmarca     =p.codmarca
Left Join PRD_MODELO      d on d.codmarca     =p.codmarca
                           and d.codmodelo    =p.codmodelo
Left Join PRD_COR         e on e.codcor       =p.codcor
Left Join TIP_COMBUSTIVEL f on f.tpcombustivel=p.tpcombustivel
;



/* View: V_FIS_NFI2 */
CREATE VIEW V_FIS_NFI2(
    CODEMPNF,
    DATAEMI,
    NUMNF,
    TIPONF,
    NUMITEM,
    CODPROD,
    DESCRPROD,
    DESCCOMPLETA,
    CODBAR,
    SITUACAO,
    IMPOSTO,
    QTNF,
    VLTOTNF,
    VLTOTIVA10,
    VLTOTIVA05,
    VLIVA10,
    VLIVA05,
    VLTOTISENTO)
AS
Select
i.CodEmpNf,
i.DataEmi,
i.NumNf,
i.TipoNf,
i.NumItem,
i.CodProd,
p.descricao as descrProd,
p.desccompleta,
P.codbar,
i.situacao,
p.imposto,
sum(i.QtNf) as QtNf,
sum(i.vltotnf) as VltotNf,
sum((case when (coalesce(p.imposto,0) = 10) then COALESCE(cast((i.VlTotNf) as numeric(16,2)),0) end)) as VlTotIva10,
sum((case when (coalesce(p.imposto,0) = 5)  then COALESCE(cast((i.VlTotNf) as numeric(16,2)),0) end)) as VlTotIva05,
sum((case when (coalesce(p.imposto,0) = 10) then COALESCE(cast((i.VlTotNf/11) as numeric(16,2)),0) else 0 end)) as VlIva10,
sum((case when (coalesce(p.imposto,0) = 5)  then COALESCE(cast((i.VlTotNf/21) as numeric(16,2)),0) else 0 end)) as VLIva05,
sum((case when (coalesce(p.imposto,0) = 0)  then COALESCE(cast(i.VlTotNf as numeric(16,2)),0) else 0 end)) as VLTotIsento
From FIS_NFI i
Left Join PRD_PRODUTO p on p.codprod=i.codprod
group by i.CodEmpNf,i.DataEmi,i.NumNf,i.TipoNf,i.NumItem,
i.CodProd,p.descricao,p.desccompleta,P.codbar,
i.situacao,p.imposto
;



/* View: V_GER_TERMINAL */
CREATE VIEW V_GER_TERMINAL(
    CODEMP,
    CODTERM,
    DESCTERM,
    TPVENDA,
    TESTACAIXA,
    CODPERIFNF,
    CODMODNF,
    QTITENS,
    DSCOMIT)
AS
select
i.CodEmp,
i.codterm,
i.descricao as descterm,
i.tpvenda,
i.testacaixa,
i.codperifnf,
i.codmodnf,
c.qtitens,
c.dscomit
From GER_TERMINAL i
Left Join GER_MODIMP c on c.codmod=i.codmodnf
;



/* View: V_MOV_COMISSAO */
CREATE VIEW V_MOV_COMISSAO(
    CODEMP,
    CODVEND,
    DATAMOV,
    NUMMOV,
    NOMEVEND,
    PRCOMIS,
    TIPOCOMIS,
    CODGRUPREG,
    DESCRGRUPREG,
    VLTOTBRUTO,
    VLTOTCUSTO,
    VLTOTLUCRO,
    VLTOTCOMIS)
AS
select
m.CodEmp,
m.CodVend,
m.DataMov,
m.NumMov,
v.NomeVend,
m.PrComis,
v.tipocomis,
c.codgru as codgrupreg,
c.descricao as descrgrupreg,
cast(m.vltotbruto  as numeric(16,2)) as vltotbruto,
cast(m.vltotcusto  as numeric(16,2)) as vltotcusto,
cast(m.vltotlucro  as numeric(16,2)) as vltotlucro,
cast(m.vlcomisvend as numeric(16,2)) as vltotcomis
From FCP_COMISVEND m
Left Join CAD_VEND      v on v.codvend=m.codvend
Left Join CAD_GRUREGVEN c on c.codgru =v.codgruregven
;



/* View: V_MOV_MOVVEND */
CREATE VIEW V_MOV_MOVVEND(
    CODEMP,
    CODVEND,
    DATAMOV,
    CODMOEDA,
    QTMOV,
    VLTOTMOV,
    VLCTOMOV,
    QTDEV,
    VLTOTDEV,
    VLCTODEV)
AS
select
i.CodEmp,
i.CodVend,
i.DataMov,
m.CodMoeda,
Cast(Sum(i.qtmov) as numeric(10,3)) as qtmov,
Cast(Sum(i.vltotmov) as numeric(14,2)) as vltotmov,
Cast(Sum(i.qtmov * COALESCE(pr.VlCtoUltComp,0)) as numeric(14,2)) as vlctomov,
0 as qtdev,
0 vltotdev,
0 as vlctodev
From MOV_SAII i
Left Join MOV_SAIC    m on m.codemp   =i.codemp
                       and m.datamov  =i.datamov
                       and m.nummov   =i.nummov
Left Join MOV_OPER      o on o.codoper=m.codoper
Left Join PRD_VALOR    pr on pr.codemp=i.codemp
                        and pr.codprod=i.codprod
Where  m.tpopermov   =1
   and m.CodSituacao =4
   and o.CalcComissao='S'
Group by i.CodEmp, i.CodVend, i.DataMov,m.CodMoeda
Union
select
i.CodEmp,
i.CodVend,
i.DataMov,
m.CodMoeda,
0 as qtmov,
0 vltotmov,
0 as vlctomov,
Cast(Sum(i.qtmov) as numeric(10,3)) as qtdev,
Cast(Sum(i.vltotmov) as numeric(14,2)) as vltotdev,
Cast(Sum(i.qtmov * COALESCE(pr.VlCtoUltComp,0)) as numeric(14,2)) as vlctodev
From MOV_SAII i
Left Join MOV_SAIC    m on m.codemp   =i.codemp
                       and m.datamov  =i.datamov
                       and m.nummov   =i.nummov
Left Join MOV_OPER      o on o.codoper=m.codoper
Left Join PRD_VALOR    pr on pr.codemp=i.codemp
                        and pr.codprod=i.codprod
Where  m.tpopermov   =3
   and m.CodSituacao =4
   and o.CalcComissao='S'
Group by i.CodEmp, i.CodVend, i.DataMov,m.CodMoeda
;



/* View: V_MOV_COMISVEN */
CREATE VIEW V_MOV_COMISVEN(
    CODEMP,
    CODVEND,
    NOMEVEND,
    PERCOMIS,
    TIPOCOMIS,
    DATAMOV,
    CODMOEDA,
    QTMOV,
    QTDEV,
    QTVENLIQ,
    VLTOTMOV,
    VLTOTDEV,
    VLVENLIQ,
    VLCTOMOV,
    VLCTODEV,
    VLCTOLIQ,
    VLLUCRO,
    VLCOMISBRUTO,
    VLCOMISLIQ)
AS
select
m.CodEmp,
m.CodVend,
v.NomeVend,
v.PerComis,
v.tipocomis,
m.DataMov,
m.CodMoeda,
m.qtmov,
m.qtdev,
coalesce(m.qtmov, 0) - coalesce(m.qtdev,0) as qtvenliq,
m.vltotmov,
m.vltotdev,
coalesce(m.vltotmov,0) - coalesce(m.vltotdev,0) as vlvenliq,
m.vlctomov,
m.vlctodev,
coalesce(m.vlctomov,0) - coalesce(m.vlctodev,0) as vlctoliq,
coalesce(m.vltotmov,0) - coalesce(m.vlctomov,0) as vllucro,
(coalesce(m.vltotmov,0) * coalesce(v.PerComis,0) / 100) as vlcomisbruto,
((coalesce(m.vltotmov,0) - coalesce(m.vlctomov,0)) * coalesce(v.PerComis,0) / 100) as vlcomisliq
From V_MOV_MOVVEND m
Left Join CAD_VEND v on v.codvend=m.codvend
;



/* View: V_MOV_SAIC */
CREATE VIEW V_MOV_SAIC(
    CODEMP,
    DATAMOV,
    NUMMOV,
    DATARES,
    NUMRES,
    CODEMPTRANS,
    DATAMOVTRANS,
    NUMMOVTRANS,
    TPOPERMOV,
    TIPOOPER,
    CODCLIENTE,
    CODVEND,
    CODCOND,
    CODMOEDA,
    CODOPER,
    CODGUIA,
    NOMEGUIA,
    CODSITUACAO,
    SITUACAONF,
    SITUACAOENTREGA,
    USUENTREGA,
    DATAENTREGA,
    HORAENTREGA,
    PERDESC,
    USUARIO,
    DATAATU,
    HORAATU,
    DESCROPER,
    NOMECLI,
    TELEFONECLI,
    NOMEVEND,
    NOMEEMP,
    NUMNOTA,
    DATANOTA,
    NUMTIMBRADO,
    DATAPREV,
    HORAPREV,
    DSSERIE,
    NUMFAT,
    DATAFAT,
    DESCRCOND,
    OBS,
    NOMEMOEDA,
    SIMBOLO,
    DESCRSIT,
    SITUACAOPGTO,
    VLTOTFATCREDITO,
    TIPOPAGTO,
    VLENTRADA,
    SELECAO,
    QTMOV,
    VLCREDCLI,
    VLTOTFAT,
    VLTOTCHEQUE,
    VLTOTDESC,
    VLTOTFRETE,
    VLTOTMOV)
AS
select
m.CodEmp,
m.DataMov,
m.NumMov,
n.DataRes,
n.NumRes,
m.CodEmptrans,
m.DataMovtrans,
m.NumMovtrans,
m.TpOperMov,
o.TipoOper,
m.CodCliente,
m.CodVend,
m.CodCond,
m.CodMoeda,
m.CodOper,
m.codguia,
d.nome as nomeGuia,
m.CodSituacao,
m.situacaoNF,
m.situacaoentrega,
m.usuentrega,
m.dataentrega,
m.horaentrega,
m.PerDesc,
m.Usuario,
m.DataAtu,
m.HoraAtu,
o.Descricao as DescrOper,
c.Nome as Nomecli,
c.numtelefone1 as telefonecli,
v.NomeVend as NomeVend,
r.Nome as NomeEmp,
m.numnota,
m.datanota,
m.numtimbrado,
m.dataprev,
m.horaprev,
m.dsserie,
m.numfat,
m.datafat,
mp.Descricao as DescrCond,
m.obs,
mo.NomeMoeda,
mo.Simbolo,
s.Descricao as DescrSit,
m.situacaopgto,
(select sum(y.vlfatura) from fcr_fat y
      where y.codemp=m.codemp and y.codcliente=m.codcliente
        and y.datamov=m.datamov and y.nummov=m.nummov)
as vlTotFatCredito,
o.tipopagto,
COALESCE(m.vlentrada,0) as vlentrada,
'F' as selecao,
COALESCE(m.qtmov,0) as qtmov,
c.vlmaxcredito as vlcredcli,
(select sum(f.vlfatura) as vlfatura from fcr_fat f
      where f.codemp=m.codemp and f.codcliente=m.codcliente
            and f.situacao='A')
as vltotfat,
(select sum(g.vlcheque) as vlcheque from fcr_chequepre g
      where g.codemp=m.codemp and g.codcliente=m.codcliente
            and g.situacao='A')
as vltotcheque,
COALESCE(m.vltotdesc,0)  as vltotdesc,
COALESCE(m.vltotfrete,0) as vltotfrete,
COALESCE(m.vltotmov,0)   as vltotmov
From MOV_SAIC m
Left Join CAD_CONDPGTOC mp on mp.codcond  =m.codcond
Left Join MOV_MOVRES    n  on n.codemp    =m.codemp
                          and n.datamov   =m.datamov
                          and n.nummov    =m.nummov
Left Join ADM_EMPRESA   r  on r.codemp    =m.codemp
Left Join MOV_OPER      o  on o.codoper   =m.codoper
Left Join CAD_CLIENTE   c  on c.codcliente=m.codcliente
Left Join CAD_CLIENTE   d  on d.codcliente=m.codguia
Left Join CAD_VEND      v  on v.codvend   =m.codvend
Left Join CAD_MOEDA    mo  on mo.codmoeda =m.codmoeda
Left Join TIP_SITMOV     s on s.tpsitmov  =m.codsituacao
;



/* View: V_PRD_PRDEMP */
CREATE VIEW V_PRD_PRDEMP(
    CODEMP,
    CODGRU,
    CODSUB,
    INMP,
    INPA,
    INMC,
    ININATIVO,
    CODITEM1,
    CODITEM2,
    CODPROD,
    DESCITEM2,
    DESCRICAO,
    DESCCOMPLETA,
    UNIDMEDIDA,
    IMPOSTO,
    CODBAR,
    DESCRICAOGRU,
    DESCCOMPLETAGRU,
    NIVELG,
    DESCRICAOSUB,
    DESCCOMPLETASUB,
    NIVELS,
    CODGRUSUB,
    CODGRUSUBITEM)
AS
Select
e.CodEmp,
e.CodGru,
e.CodSub,
e.InMp,
e.InPa,
e.InMc,
e.InInativo,
p.CodItem1,
p.CodItem2,
p.CodProd,
p.DescItem2,
p.Descricao,
p.DescCompleta,
p.UnidMedida,
p.Imposto,
p.CodBar,
g.Descricao as DescricaoGru,
g.DescCompleta as DescCompletaGru,
g.Descnivel as NivelG,
s.Descricao as DescricaoSub,
s.DescCompleta as DescCompletaSub,
s.Descnivel as NivelS,
(e.CodGru || '.' || e.CodSub) as CodGruSub,
(e.CodGru || '.' || e.CodSub || '.' || p.CodItem1 || '.' || p.CodItem2) as CodGruSubItem
From PRD_GSEMP E
Left Join PRD_PRODUTO P  on p.codgru=e.codgru and p.codsub=e.codsub
Left Join PRD_GRUPO G    on g.codgru=e.codgru
Left Join PRD_SUBGRUPO S on s.codgru=e.codgru and s.codsub=e.codsub
;



/* View: V_PRD_PRDQTVL */
CREATE VIEW V_PRD_PRDQTVL(
    CODEMP,
    CODGRU,
    CODSUB,
    CODITEM1,
    CODITEM2,
    CODPROD,
    DESCITEM2,
    DESCRICAO,
    DESCCOMPLETA,
    UNIDMEDIDA,
    IMPOSTO,
    CODBAR,
    DESCRICAOGRU,
    DESCCOMPLETAGRU,
    NIVELG,
    DESCRICAOSUB,
    DESCCOMPLETASUB,
    NIVELS,
    CODGRUSUB,
    CODGRUSUBITEM,
    INGENERICO,
    CODLOTE,
    CODMARCAFOR,
    DESCMARCAFOR,
    DESCSITPROD,
    NUMLOTEFORN,
    DATAVENCLOTE,
    SITUACAOLOTE,
    DESCRITEM1,
    DATACADASTRO,
    DATAALTVL,
    DATAALTQTDE,
    CODNIVEL,
    USUARIOINC,
    SELECAO,
    MOEDACOMPRA,
    NOMEMOEDA,
    INATIVO,
    CODSITPROD,
    QTTEMPO,
    CORSIMBOLO,
    DTULTVENDA,
    DTULTCOMPRA,
    INMATERIAPRIMA,
    QTFISICA,
    QTEMPENHADA,
    QTRESERVA,
    QTVENDIDA,
    QRMA,
    QTTERCEIRO,
    QTMINIMA,
    QTMAXIMA,
    QTFRACIONADA,
    QTDISP,
    VLVENDA,
    VLVENDAVAREJOMIN,
    VLVENDAVAREJOFIM,
    VLVENDAMIN,
    VLVENDAMAX,
    VLVENDAATACADO,
    VLPROMOCIONAL,
    VLCTOULTCOMP,
    MARGEM,
    MARGEMVAREJOINI,
    MARGEMVAREJOFIM,
    MARGEM1,
    MARGEM2,
    MARGEM3,
    PERCDESCMAX)
AS
Select
e.CodEmp,
e.CodGru,
e.CodSub,
e.CodItem1,
e.CodItem2,
e.CodProd,
e.DescItem2,
e.Descricao,
e.DescCompleta,
e.UnidMedida,
e.Imposto,
e.CodBar,
e.DescricaoGru,
e.DescCompletaGru,
e.NivelG,
e.DescricaoSub,
e.DescCompletaSub,
e.NivelS,
e.CodGruSub,
e.CodGruSubItem,
d.ingenerico,
(Select First 1 h.codlote from PRD_LOTE H 
        where h.codprod = e.codprod
         and  h.situacao='A')
as codlote,
d.CodMarcaFor,
f.descricao as descmarcafor,
m.descricao as descSitProd,
s.DsLote as NumLoteForn,
s.DataVencto as DataVencLote,
s.Situacao as SituacaoLote,
i.descricao as DescrItem1,
d.Datainc as DataCadastro,
v.Dataatu as DataAltVl,
q.DataAtu as DataAltQtde,
(d.CodGru ||'.'|| d.CodSub ||'.'|| d.CodItem1 ||'.'|| d.CodItem2) as CodNivel,
d.UsuarioInc,
'F' as Selecao,
v.MoedaCompra,
j.NomeMoeda,
q.Inativo,
d.codsitprod,
g.qttempo,
g.corsimbolo,
q.dtultvenda,
q.dtultcompra,
d.inmateriaprima,
COALESCE(q.QTfisica,0)       as QtFisica,
COALESCE(q.QtEmpenhada,0)    as QtEmpenhada,
COALESCE(q.QtReserva,0)      as QtReserva,
COALESCE(q.QtVendida,0)      as QtVendida,
COALESCE(q.QtRma,0)          as QRma,
COALESCE(q.QtTerceiro,0)     as QtTerceiro,
COALESCE(q.QtMinima,0)       as QtMinima,
COALESCE(q.QtMaxima,0)       as QtMaxima,
COALESCE(q.QtFracionada,0)   as QtFracionada,
COALESCE((q.QTfisica - q.QtReserva),0) as QtDisp,
case
   when v.moedacompra <> 3 then
       coalesce(cast(v.VlVenda as numeric(14,4)),0)
   else
       coalesce(cast(v.VlVenda as numeric(14,0)),0)
end as VlVenda,
case
   when v.moedacompra <> 3 then
       coalesce(cast(v.vlvarejoini as numeric(14,4)),0)
   else
       coalesce(cast(v.vlvarejoini as numeric(14,0)),0)
end as VlVendaVarejoMin,
case
   when v.moedacompra <> 3 then
       coalesce(cast(v.VlVarejofim as numeric(14,4)),0)
   else
       coalesce(cast(v.VlVarejofim as numeric(14,0)),0)
end as VlVendaVarejoFim,
case
   when v.moedacompra<> 3 then
       coalesce(cast(v.VlVendaMin as numeric(14,4)),0)
   else
       coalesce(cast(v.VlVendaMin as numeric(14,0)),0)
end as VlVendaMin,
case
   when v.moedacompra <> 3 then
       coalesce(cast(v.VlVendaMax as numeric(14,4)),0)
   else
       coalesce(cast(v.VlVendaMax as numeric(14,0)),0)
end as VlVendaMax,
case
   when v.moedacompra <> 3 then
       coalesce(cast(v.VlVendaAtacado as numeric(14,4)),0)
   else
       coalesce(cast(v.VlVendaAtacado as numeric(14,0)),0)
end as VlVendaAtacado,
case
   when v.moedacompra <> 3 then
       coalesce(cast(v.vlpromocional as numeric(14,4)),0)
   else
       coalesce(cast(v.vlpromocional as numeric(14,0)),0)
end as Vlpromocional,
case
   when v.moedacompra <> 3 then
       coalesce(cast(v.VlCtoUltComp as numeric(14,4)),0)
   else
       coalesce(cast(v.VlCtoUltComp as numeric(14,0)),0)
end as VlCtoUltComp,
COALESCE(v.margem,0)         as margem,
COALESCE(v.prmargvarini,0)   as margemVarejoIni,
COALESCE(v.prmargvarfim,0)   as margemVarejoFim,
COALESCE(v.margem1,0)        as margem1,
COALESCE(v.margem2,0)        as margem2,
COALESCE(v.margem3,0)        as margem3,
COALESCE(v.percdescmax,0)    as percdescmax
From V_PRD_PRDEMP E
left Join ADM_PARAM C on   c.codemp    =e.codemp
Left Join PRD_PRODUTO D on d.codprod   =e.codprod
Left Join PRD_MARCA   F on f.codmarca  =d.codmarcafor
Left Join TIP_SITPROD M on m.codsitprod=d.codsitprod
Left Join PRD_ITEM1 I on   i.coditem1  =d.coditem1
Left Join PRD_QTDE  Q on   q.codemp    =e.codemp
                       and q.codprod   =e.codprod
Left Join PRD_VALOR V on   v.codemp    =e.codemp
                       and v.codprod   =e.codprod
Left Join PRD_LOTE  S on   s.codprod   =d.codprod
                       and s.codlote   =d.codlote
Left Join CAD_MOEDA J on   cast(j.codmoeda as varchar(1))=v.moedacompra
Left Join TIP_SITPROD G on g.codsitprod=d.codsitprod
;



/* View: V_MOV_ENTSAI */
CREATE VIEW V_MOV_ENTSAI(
    TIPOMOV,
    CODEMP,
    DATAMOV,
    NUMMOV,
    NUMITEM,
    CODPROD,
    CODGRU,
    CODSUB,
    CODITEM1,
    CODITEM2,
    CODCLIENTE,
    NOMECLI,
    CODVEND,
    NOMEVEND,
    CODCOMPVEND,
    TPOPERMOV,
    CODOPER,
    TPOPEREST,
    CODSITUACAO,
    ATUALIZAEST,
    DESCRPROD,
    CODMOEDA,
    CODMARCAFOR,
    DESCMARCAFOR,
    DESCRICAOGRU,
    DESCRICAOSUB,
    NOMECOMPVEND,
    DESCROPER,
    DESCRSIT,
    QTMOVENT,
    QTMOVSAI,
    VLTOTFRETE,
    VLTOTDESC,
    VLUNITBRUTO,
    VLUNITMOV,
    VLTOTMOV)
AS
select
'SAIDA' as TipoMov,
i.CodEmp,
i.DataMov,
i.NumMov,
i.NumItem,
i.CodProd,
p.CodGru,
p.CodSub,
p.CodItem1,
p.CodItem2,
m.Codcliente,
m.nomecli,
m.codVend,
m.nomeVend,
i.CodVend as CodCompVend,
m.TpOperMov,
m.CodOper,
o.codestoper as tpoperest,
m.CodSituacao,
o.AtualizaEst,
p.Descricao as DescrProd,
m.codmoeda,
p.codmarcafor,
p.descmarcafor,
p.DescricaoGru,
p.DescricaoSub,
v.NomeVend as NomeCompVend,
o.Descricao as DescrOper,
s.Descricao as DescrSit,
0 as QtMovEnt,
i.QtMov as QtMovSai,
COALESCE(i.VlTotFrete,0) as Vltotfrete,
COALESCE(i.VlTotdesc,0) as Vltotdesc,
COALESCE(cast((i.VlUnitMov-i.vltotfrete+i.vltotdesc) as numeric(16,2)),0) as VlUnitBruto,
COALESCE(i.VlUnitMov,0) as VlUnitMov,
COALESCE(i.VlTotMov,0)  as VlTotMov
From MOV_SAII i
Left Join V_MOV_SAIC     m on m.codemp  =i.codemp
                          and m.datamov =i.datamov
                          and m.nummov  =i.nummov
Left Join MOV_OPER       o on o.codoper =m.codoper
Left Join TIP_SITMOV     s on s.tpsitmov=m.codsituacao
Left Join V_PRD_PRDQTVL  p on p.codemp  =i.codemp
                          and p.codprod =i.codprod
Left Join CAD_VEND       v on v.codvend =i.codvend
Where m.tpopermov in(1,4,6,7,11,13,20,25,28,30)
Union select
'ENTRADA' as TipoMov,
i.CodEmp,
i.DataMov,
i.NumMov,
i.NumItem,
i.CodProd,
p.CodGru,
p.CodSub,
p.CodItem1,
p.CodItem2,
m.Codcliente,
m.nomecli,
m.codVend,
m.nomeVend,
i.CodVend as CodCompVend,
m.TpOperMov,
m.CodOper,
o.codestoper as tpoperest,
m.CodSituacao,
o.AtualizaEst,
p.Descricao as DescrProd,
m.codmoeda,
p.codmarcafor,
p.descmarcafor,
p.DescricaoGru,
p.DescricaoSub,
v.NomeVend as NomeCompVend,
o.Descricao as DescrOper,
s.Descricao as DescrSit,
i.QtMov as QtMovEnt,
0 as QtMovSai,
COALESCE(i.VlTotFrete,0) as Vltotfrete,
COALESCE(i.VlTotdesc,0) as Vltotdesc,
COALESCE(cast((i.VlUnitMov-i.vltotfrete+i.vltotdesc) as numeric(16,2)),0) as VlUnitBruto,
COALESCE(i.VlUnitMov,0) as VlUnitMov,
COALESCE(i.VlTotMov,0)  as VlTotMov
From MOV_SAII i
Left Join V_MOV_SAIC     m on m.codemp  =i.codemp
                          and m.datamov =i.datamov
                          and m.nummov  =i.nummov
Left Join MOV_OPER       o on o.codoper =m.codoper
Left Join TIP_SITMOV     s on s.tpsitmov=m.codsituacao
Left Join V_PRD_PRDQTVL  p on p.codemp  =i.codemp
                          and p.codprod =i.codprod
Left Join CAD_VEND       v on v.codvend =i.codvend
Where m.tpopermov in(2,3,5,8,12,14,15,18,24)
;



/* View: V_PRD_PRODUTO */
CREATE VIEW V_PRD_PRODUTO(
    CODGRU,
    CODSUB,
    CODITEM1,
    CODITEM2,
    CODPROD,
    DESCITEM2,
    DESCRICAO,
    DESCCOMPLETA,
    UNIDMEDIDA,
    CST,
    NCM,
    PESO,
    IMPOSTO,
    CODBAR,
    INFOADIC,
    USUARIOINC,
    DATAINC,
    USUARIO,
    DATAATU,
    HORAATU,
    NIVELG,
    DESCRICAOGRU,
    DESCCOMPLETAGRU,
    NIVELS,
    DESCRICAOSUB,
    DESCCOMPLETASUB,
    NIVELI,
    CODGRUSUB,
    CODGRUSUBITEM)
AS
Select
p.CodGru,
p.CodSub,
p.CodItem1,
p.CodItem2,
p.CodProd,
p.DescItem2,
p.Descricao,
p.DescCompleta,
p.UnidMedida,
p.CST,
p.NCM,
p.Peso,
p.Imposto,
p.CodBar,
p.InfoAdic,
p.UsuarioInc,
p.DataInc,
p.Usuario,
p.DataAtu,
p.HoraAtu,
g.Descnivel as NivelG,
g.Descricao as DescricaoGru,
g.DescCompleta as DescCompletaGru,
s.Descnivel as NivelS,
s.Descricao as DescricaoSub,
s.DescCompleta as DescCompletaSub,
i.Descnivel as NivelI,
(p.CodGru || '.' || p.CodSub) as CodGruSub,
(p.CodGru || '.' || p.CodSub || '.' || p.CodItem1 || '.' || p.CodItem2) as CodGruSubItem
From PRD_PRODUTO P
Left Join PRD_GRUPO G    on g.codgru=p.codgru
Left Join PRD_SUBGRUPO S on s.codgru=p.codgru and s.codsub=p.codsub
Left Join PRD_ITEM1 I    on i.coditem1=p.coditem1
;



/* View: V_MOV_ENTSAISVC */
CREATE VIEW V_MOV_ENTSAISVC(
    TIPOMOV,
    CODEMP,
    DATAMOV,
    NUMMOV,
    NUMITEM,
    CODPROD,
    CODCOMPVEND,
    QTMOVENT,
    QTMOVSAI,
    VLUNITMOV,
    VLTOTMOV,
    TPOPERMOV,
    CODOPER,
    CODSITUACAO,
    DATAPREV,
    HORAPREV,
    ATUALIZAEST,
    DESCRPROD,
    CODGRU,
    CODSUB,
    DSOBS,
    DESCRICAOGRU,
    DESCRICAOSUB,
    NOMECOMPVEND,
    DESCROPER,
    DESCRSIT)
AS
select
'SAIDA' as TipoMov,
i.CodEmp,
i.DataRes as DataMov,
i.NumRes as NumMov,
i.NumItem,
i.CodProd,
i.CodVend as CodCompVend,
0 as QtMovEnt,
i.QtMov as QtMovSai,
COALESCE(i.VlUnitMov,0) as VlUnitMov,
COALESCE(i.VlTotMov,0) as VlTotMov,
o.TpOperMov,
m.CodOper,
m.CodSituacao,
m.dataprev,
m.horaprev,
o.AtualizaEst,
p.Descricao as DescrProd,
p.CodGru,
p.CodSub,
m.obs as dsObs,
p.DescricaoGru,
p.DescricaoSub,
v.NomeVend as NomeCompVend,
o.Descricao as DescrOper,
s.Descricao as DescrSit
From MOV_RESI i
Left Join MOV_RESC       m on m.codemp  =i.codemp
                          and m.datares =i.datares
                          and m.numres  =i.numres
Left Join MOV_OPER       o on o.codoper =m.codoper
Left Join TIP_SITMOV     s on s.tpsitmov=m.codsituacao
Left Join V_PRD_PRODUTO  p on p.codprod =i.codprod
Left Join CAD_VEND       v on v.codvend =i.codvend
Where o.tpopermov = 22
Union select
'ENTRADA' as TipoMov,
i.CodEmp,
i.DataMov,
i.NumMov,
i.NumItem,
i.CodProd,
i.CodVend as CodCompVend,
i.QtMov as QtMovEnt,
0 as QtMovSai,
COALESCE(i.VlUnitMov,0) as VlUnitMov,
COALESCE(i.VlTotMov,0) as VlTotMov,
o.TpOperMov,
m.CodOper,
m.CodSituacao,
m.dataprev,
m.horaprev,
o.AtualizaEst,
p.Descricao as DescrProd,
p.CodGru,
p.CodSub,
m.obs as dsObs,
p.DescricaoGru,
p.DescricaoSub,
v.NomeVend as NomeCompVend,
o.Descricao as DescrOper,
s.Descricao as DescrSit
From MOV_SAII i
Left Join MOV_SAIC       m on m.codemp  =i.codemp
                          and m.datamov =i.datamov
                          and m.nummov  =i.nummov
Left Join MOV_OPER       o on o.codoper =m.codoper
Left Join TIP_SITMOV     s on s.tpsitmov=m.codsituacao
Left Join V_PRD_PRODUTO  p on p.codprod =i.codprod
Left Join CAD_VEND       v on v.codvend =i.codvend
Where o.tpopermov = 23
;



/* View: V_MOV_MOEDA */
CREATE VIEW V_MOV_MOEDA(
    CODEMP,
    DATAMOV,
    NUMMOV,
    TPMOV,
    TIPOCALC,
    CODMOEDA,
    VALOR,
    USUARIO,
    DATAATU,
    HORAATU,
    NOMEMOEDA,
    SIMBOLO)
AS
select
m.CodEmp,
m.DataMov,
m.NumMov,
m.TpMov,
e.tipocalc,
m.CodMoeda,
m.Valor,
m.Usuario,
m.DataAtu,
m.HoraAtu,
mo.NomeMoeda,
mo.Simbolo
From MOV_MOEDA m
Left Join CAD_MOEDA mo   on mo.codmoeda=m.codmoeda
Left Join CAD_COTMOEDA e on  e.codemp  =m.codemp
                         and e.codmoeda=m.codmoeda
                         and e.datacot =m.datamov
;



/* View: V_MOV_MOVCONTROL */
CREATE VIEW V_MOV_MOVCONTROL(
    CODEMP,
    DATARES,
    NUMRES,
    DATACONTROL,
    NUMCONTROL,
    USUARIO,
    TPSERVICO,
    DSSERVICO,
    DSUSUARIO,
    SITCONTROL,
    SITMOVRES,
    DTTEMPOINI,
    DTTEMPOFIM,
    CODMOEDA,
    QTTEMPO,
    CODVEND,
    NOMEVEND,
    CODPESSOA,
    NOMEPESSOA,
    DSSITCONTROL,
    DSSITMOVRES,
    USUARIOINC,
    DATAATU,
    HORAATU,
    QTVOLUME,
    VLTOTAL,
    SELECAO)
AS
Select
m.CodEmp,
m.datares,
m.NumRes,
m.datacontrol,
m.numcontrol,
m.usuario,
m.tpservico,
j.descricao as DsServico,
p.nome as dsusuario,
m.situacao as sitcontrol,
c.codsituacao as sitmovres,
m.dttempoini,
m.dttempofim,
c.codmoeda,
m.qttempo,
c.codvend,
e.nomevend,
c.codpessoa,
c.nomepessoa,
h.descricao as dssitcontrol,
g.descricao as dssitmovres,
m.usuarioinc,
m.dataatu,
m.HoraAtu,
coalesce(m.qtvolume,0) as qtvolume,
coalesce(m.vltotal,0)  as vltotal,
'F' as selecao
From MOV_MOVCONTROL m
Left Join MOV_RESC       c on c.codemp      =m.codemp
                          and c.datares     =m.datares
                          and c.numres      =m.numres
Left Join CAD_VEND       e on e.codvend     =c.codvend
Left Join CAD_CLIENTE    f on f.codcliente  =c.codpessoa
Left Join TIP_SITMOV     g on g.tpsitmov    =c.codsituacao
Left Join TIP_SITCONTROL h on h.tpsitcontrol=m.situacao
Left Join ADM_USUARIO    p on p.codusu      =m.usuario
Left Join TIP_SERVICO    j on j.codserv     =m.tpservico
;



/* View: V_MOV_MOVMOEDA */
CREATE VIEW V_MOV_MOVMOEDA(
    DATAMOV,
    CODPROD,
    UNIDMEDIDA,
    CODCOMPVEND,
    TPOPERMOV,
    CODOPER,
    CODMOEDA,
    NOMEMOEDA,
    MOEDACOMPRA,
    NOMEMOEDACOMPRA,
    CODSITUACAO,
    ATUALIZAEST,
    DESCRPROD,
    CODGRU,
    CODSUB,
    DESCRICAOGRU,
    DESCRICAOSUB,
    NOMECOMPVEND,
    DESCROPER,
    DESCRSIT,
    VLCTOULTCOMP,
    VLUNITMOV,
    QTMOV,
    VLTOTMOV)
AS
Select
i.Datamov,
i.CodProd,
pr.unidmedida,
i.CodVend as CodCompVend,
m.TpOperMov,
m.CodOper,
m.codmoeda,
j.nomemoeda,
pr.moedacompra,
k.nomemoeda as nomemoedacompra,
m.CodSituacao,
o.AtualizaEst,
pr.Descricao as DescrProd,
pr.CodGru,
pr.CodSub,
pr.DescricaoGru,
pr.DescricaoSub,
v.NomeVend as NomeCompVend,
o.Descricao as DescrOper,
s.Descricao as DescrSit,
pr.vlctoultcomp,
i.vlunitmov,
Sum(COALESCE(i.qtmov,0)) as qtmov,
Sum(COALESCE(i.vltotmov,0)) as vltotmov
From MOV_SAII i
Left Join MOV_SAIC       m on m.codemp  =i.codemp
                          and m.datamov =i.datamov
                          and m.nummov  =i.nummov 
Left Join MOV_OPER       o on o.codoper =m.codoper
Left Join TIP_SITMOV     s on s.tpsitmov=m.codsituacao
Left Join V_PRD_PRDQTVL pr on pr.codemp =i.codemp
                          and pr.codprod=i.codprod
Left Join CAD_VEND       v on v.codvend =i.codvend
Left Join CAD_MOEDA      j on j.codmoeda=m.codmoeda
Left Join CAD_MOEDA      k on k.codmoeda=pr.moedacompra
Group By i.datamov,i.CodProd,pr.unidmedida,i.CodVend,m.TpOperMov,m.CodOper,m.codmoeda,j.nomemoeda,
pr.moedacompra,k.nomemoeda,m.CodSituacao,o.AtualizaEst,pr.Descricao,pr.CodGru,pr.CodSub,pr.DescricaoGru,pr.DescricaoSub,v.NomeVend,
o.Descricao,s.Descricao,pr.vlctoultcomp,i.vlunitmov
;



/* View: V_MOV_RESC */
CREATE VIEW V_MOV_RESC(
    CODEMP,
    DATARES,
    NUMRES,
    CODSITUACAO,
    CODCOND,
    CODGUIA,
    NOMEGUIA,
    CODOPER,
    TPOPERMOV,
    TIPOOPER,
    NUMRESORI,
    DATARESORI,
    DESCROPER,
    DESCRCOND,
    CODPESSOA,
    NOMEPESSOA,
    DATAPREV,
    HORAPREV,
    OBS,
    USUARIO,
    DATAATU,
    HORAATU,
    CODVEND,
    NOMEVEND,
    DESCRSIT,
    CODMOEDA,
    NOMEMOEDA,
    NUMMOVPED,
    DATAMOVPED,
    STATUSATU,
    QTMOV,
    VLCREDCLI,
    VLTOTFAT,
    VLTOTCHEQUE,
    VLTOTMOV,
    VLTOTDESC,
    SELECAO)
AS
select
m.CodEmp,
m.DataRes,
m.NumRes,
m.CodSituacao,
m.CodCond,
m.codGuia,
m.nomeGuia,
m.CodOper,
e.tpopermov,
e.tipooper,
m.numresori,
m.dataresori,
e.descricao as descroper,
c.descricao as descrcond,
m.CodPessoa,
m.NomePessoa,
m.dataprev,
m.horaprev,
m.obs,
m.Usuario,
m.DataAtu,
m.HoraAtu,
m.CodVend,
v.NomeVend as NomeVend,
s.Descricao as DescrSit,
m.codmoeda,
j.nomemoeda,
m.nummovped,
m.datamovped,
m.statusatu,
COALESCE(m.qtmov,0) as qtmov,
d.vlmaxcredito as vlcredcli,
(select sum(f.vlfatura) from fcr_fat f
      where f.codemp=m.codemp and f.codcliente=m.codpessoa
            and f.situacao='A')
as vltotfat,
(select sum(g.vlcheque) from fcr_chequepre g
      where g.codemp=m.codemp and g.codcliente=m.codpessoa
            and g.situacao='A')
as vltotcheque,
COALESCE(m.vltotmov,0) as vltotmov,
COALESCE(m.vltotdesc,0) as vltotdesc,
'F' as selecao
From MOV_RESC m
Left Join CAD_CLIENTE   d on d.codcliente=m.codpessoa
Left Join CAD_MOEDA     j on j.codmoeda  =m.codmoeda
Left Join CAD_VEND      v on v.codvend   =m.codvend
Left Join TIP_SITMOV    s on s.tpsitmov  =m.codsituacao
Left Join CAD_CONDPGTOC c on c.codcond   =m.codcond
Left Join MOV_OPER      e on e.codoper   =m.codoper
;



/* View: V_MOV_MOVRES */
CREATE VIEW V_MOV_MOVRES(
    CODEMP,
    DATAMOV,
    NUMMOV,
    CODEMPRES,
    DATARES,
    NUMRES,
    CODCOND,
    CODOPER,
    DESCROPER,
    CODVEND,
    NOMEVEND,
    CODSITUACAO,
    DESCRSIT,
    NOMEPESSOA,
    QTMOV,
    VLTOTMOV,
    USUARIO,
    DATAATU,
    HORAATU)
AS
select
m.CodEmp,
m.DataMov,
m.NumMov,
m.CodEmpRes,
m.DataRes,
m.NumRes,
r.codcond,
r.codoper,
r.descroper,
r.CodVend,
v.NomeVend as NomeVend,
r.CodSituacao,
r.DescrSit,
r.NomePessoa,
r.qtmov,
r.vltotmov,
m.Usuario,
m.DataAtu,
m.HoraAtu
From MOV_MOVRES m
Left Join V_MOV_RESC r on r.codemp =m.codemp
                      and r.datares=m.datares
                      and r.numres =m.numres
Left Join CAD_VEND   v on v.codvend=r.codvend
;



/* View: V_MOV_MOVSVC */
CREATE VIEW V_MOV_MOVSVC(
    TIPOMOV,
    CODEMP,
    DATAMOV,
    NUMMOV,
    CODCLIFOR,
    CODCOMPVEND,
    TPOPERMOV,
    CODOPER,
    DOCCLIFOR,
    CODSITUACAO,
    DATAPREV,
    HORAPREV,
    DSOBS,
    NOMECLIFOR,
    NOMECOMPVEND,
    DESCROPER,
    DESCRSIT,
    VLUNITMOV,
    QTMOVENT,
    QTMOVSAI,
    VLTOTMOV)
AS
select
'SAIDA' as TipoMov,
i.CodEmp,
i.DataRes as DataMov,
i.NumRes as NumMov,
i.codpessoa as codclifor,
i.CodVend as CodCompVend,
o.TpOperMov,
i.CodOper,
n.docfiscal as docclifor,
i.CodSituacao,
i.dataprev,
i.horaprev,
i.obs as dsObs,
n.nome as nomeclifor,
v.NomeVend as NomeCompVend,
o.Descricao as DescrOper,
s.Descricao as DescrSit,
COALESCE(m.VlUnitMov,0) as VlUnitMov,
0 as QtMovEnt,
Sum(cast(m.qtmov as numeric(10,3))) as qtMovSai,
Sum(cast(m.vltotmov as numeric(16,2))) as vltotmov
From MOV_RESC i
Left Join MOV_RESI       m on m.codemp    =i.codemp
                          and m.datares   =i.datares
                          and m.numres    =i.numres
Left Join MOV_OPER       o on o.codoper   =i.codoper
Left Join CAD_CLIENTE    n on n.codcliente=i.codpessoa
Left Join TIP_SITMOV     s on s.tpsitmov  =i.codsituacao
Left Join CAD_VEND       v on v.codvend   =i.codvend
Where o.tpopermov = 22
Group by i.codemp,i.datares,i.numres,i.codpessoa,i.codvend,
o.tpopermov,i.codoper,n.docfiscal,i.codsituacao,i.dataprev,i.horaprev,i.obs,
n.nome,v.nomevend,o.descricao,s.descricao,m.vlunitmov
Union select
'ENTRADA' as TipoMov,
i.CodEmp,
i.DataMov,
i.NumMov,
i.codcliente as codclifor,
i.CodVend as CodCompVend,
o.TpOperMov,
i.CodOper,
n.docfiscal as docclifor,
i.CodSituacao,
i.dataprev,
i.horaprev,
i.obs as dsObs,
n.nome as nomeclifor,
v.NomeVend as NomeCompVend,
o.Descricao as DescrOper,
s.Descricao as DescrSit,
COALESCE(m.VlUnitMov,0) as VlUnitMov,
Sum(cast(m.qtmov as numeric(10,3))) as qtmovEnt,
0 as QtMovSai,
Sum(cast(m.vltotmov as numeric(16,2))) as vltotmov
From MOV_SAIC i
Left Join MOV_SAII       m on m.codemp  =i.codemp
                          and m.datamov =i.datamov
                          and m.nummov  =i.nummov
Left Join MOV_OPER       o on o.codoper =i.codoper
Left Join TIP_SITMOV     s on s.tpsitmov=i.codsituacao
Left Join CAD_CLIENTE    n on n.codcliente=i.codcliente
Left Join CAD_VEND       v on v.codvend =i.codvend
Where o.tpopermov = 23
Group by i.codemp,i.datamov,i.nummov,i.codcliente,i.codvend,
o.tpopermov,i.codoper,n.docfiscal,i.codsituacao,i.dataprev,i.horaprev,i.obs,
n.nome,v.nomevend,o.descricao,s.descricao,m.vlunitmov
;



/* View: V_MOV_PAG */
CREATE VIEW V_MOV_PAG(
    CODEMPMOV,
    DATAMOV,
    NUMMOV,
    CODEMPCX,
    CODTERM,
    DATAABERT,
    NUMSEQCX,
    NUMSEQITEM,
    USUARIO,
    DATAATU,
    HORAATU,
    DATALANCTO,
    TPDOC,
    CODHIST,
    VLDOC,
    VLCONTADO,
    VLDIFERENCA,
    CODPORT,
    NUMDOC,
    NUMDOCAUX,
    DESCRDOC,
    DESCRHIST,
    CODFORNEC,
    NOMEFOR,
    CODCOMP,
    NOMECOMP,
    CODCOND,
    DESCRCOND,
    QTMOV,
    VLTOTMOV)
AS
select
p.CodEmpMov,
p.DataMov,
p.NumMov,
p.CodEmpCx,
p.CodTerm,
p.DataAbert,
p.NumSeqCx,
p.NumSeqItem,
p.Usuario,
p.DataAtu,
p.HoraAtu,
c.DataLancto,
c.TpDoc,
c.CodHist,
c.VlDoc,
c.VlContado,
c.VlDiferenca,
c.CodPort,
c.NumDoc,
c.NumDocAux,
d.descricao as descrdoc,
h.descricao as descrhist,
m.codcliente as codfornec,
m.nomecli as nomefor,
m.codvend as codcomp,
m.nomevend as nomecomp,
m.codcond,
m.descrcond,
m.qtmov,
m.vltotmov
From MOV_PAG p
Left Join FCX_CAIXAI c on c.codemp=p.codempcx
 and c.codterm=p.codterm and c.dataabert=p.dataabert
 and c.numseqcx=p.numseqcx and c.numseqitem=p.numseqitem
Left Join TIP_DOCFIN d on d.tpdoc=c.tpdoc
Left Join FCX_HIST h on h.codhist=c.codhist
Left Join V_MOV_SAIC m on m.codemp=p.codempmov
 and m.datamov=p.datamov and m.nummov=p.nummov
;



/* View: V_MOV_REC */
CREATE VIEW V_MOV_REC(
    CODEMPMOV,
    DATAMOV,
    NUMMOV,
    CODEMPCX,
    CODTERM,
    DATAABERT,
    NUMSEQCX,
    NUMSEQITEM,
    USUARIO,
    DATAATU,
    HORAATU,
    DATALANCTO,
    TPDOC,
    CODMOEDA,
    SIMBOLO,
    CODHIST,
    VLDOC,
    VLCONTADO,
    VLDIFERENCA,
    CODPORT,
    NUMDOC,
    NUMDOCAUX,
    DESCRDOC,
    DESCRHIST,
    CODCLIENTE,
    NOMECLI,
    CODVEND,
    NOMEVEND,
    CODCOND,
    DESCRCOND,
    QTMOV,
    VLTOTMOV)
AS
select
r.CodEmpMov,
r.DataMov,
r.NumMov,
r.CodEmpCx,
r.CodTerm,
r.DataAbert,
r.NumSeqCx,
r.NumSeqItem,
r.Usuario,
r.DataAtu,
r.HoraAtu,
c.DataLancto,
c.TpDoc,
m.codmoeda,
f.simbolo,
c.CodHist,
c.VlDoc,
c.VlContado,
c.VlDiferenca,
c.CodPort,
c.NumDoc,
c.NumDocAux,
d.descricao as descrdoc,
h.descricao as descrhist,
m.codcliente,
m.nomecli,
m.codvend,
m.nomevend,
m.codcond,
m.descrcond,
m.qtmov,
m.vltotmov
From MOV_REC r
Left Join FCX_CAIXAI c on c.codemp    =r.codempcx
                      and c.codterm   =r.codterm
                      and c.dataabert =r.dataabert
                      and c.numseqcx  =r.numseqcx
                      and c.numseqitem=r.numseqitem
Left Join TIP_DOCFIN d on d.tpdoc     =c.tpdoc
Left Join FCX_HIST h   on h.codhist   =c.codhist
Left Join V_MOV_SAIC m on m.codemp    =r.codempmov
                      and m.datamov   =r.datamov
                      and m.nummov    =r.nummov
Left Join FGR_DOCREL e on e.codemp    =r.codempcx
                      and e.tpdoc     =c.tpdoc
Left Join CAD_MOEDA  f on f.codmoeda  =m.codmoeda
;



/* View: V_MOV_RELMOV */
CREATE VIEW V_MOV_RELMOV(
    CODEMPORI,
    DATAMOVORI,
    NUMMOVORI,
    TPMOVORI,
    CODEMPDES,
    DATAMOVDES,
    NUMMOVDES,
    TPMOVDES,
    TPRELMOV,
    TPOPERMOVORI,
    DESCROPERMOVORI,
    TPOPERMOVDES,
    DESCROPERMOVDES,
    CODSITORI,
    DESCRSITORI,
    CODSITDES,
    DESCRSITDES)
AS
select
r.CodEmpOri,
r.DataMovOri,
r.NumMovOri,
r.TpMovOri,
r.CodEmpDes,
r.DataMovDes,
r.NumMovDes,
r.TpMovDes,
r.TpRelMov,
s.TpOperMov as TpOperMovOri,
os.Descricao as DescrOperMovOri,
e.TpOperMov as TpOperMovDes,
oe.Descricao as DescrOperMovDes,
s.CodSituacao as CodSitOri,
ss.Descricao as DescrSitOri,
e.CodSituacao as CodSitDes,
se.Descricao as DescrSitDes
From MOV_RELMOV r
Left Join MOV_SAIC       s on s.codemp    =r.codempori
   and s.datamov=r.datamovori and s.nummov=r.nummovori
Left Join MOV_SAIC       e on e.codemp    =r.codempdes
   and e.datamov=r.datamovdes and e.nummov=r.nummovdes
Left Join TIP_SITMOV    ss on ss.tpsitmov =s.codsituacao
Left Join TIP_SITMOV    se on se.tpsitmov =e.codsituacao
Left Join TIP_OPERMOV   os on os.tpopermov =s.tpopermov
Left Join TIP_OPERMOV   oe on oe.tpopermov =e.tpopermov
Where r.TpRelMov=1
;



/* View: V_MOV_RESI */
CREATE VIEW V_MOV_RESI(
    CODEMP,
    DATARES,
    NUMRES,
    NUMITEM,
    CODPROD,
    CODVEND,
    CODCOND,
    CODMOEDA,
    NOMEMOEDA,
    CODGUIA,
    NOMEGUIA,
    CODOPER,
    TPOPERMOV,
    NUMRESORI,
    DATARESORI,
    DESCRPRODGEN,
    DESCROPER,
    DESCRCOND,
    CODPESSOA,
    NOMEPESSOA,
    DATAPREV,
    HORAPREV,
    OBS,
    CODSITUACAO,
    DESCRSIT,
    QTMOV,
    TIPOOPER,
    CODBAR,
    QTMOVANT,
    VLUNITMOV,
    VLCUSTOMOV,
    VLTOTDESC,
    VLTOTMOV,
    PERDESC,
    USUARIO,
    DATAATU,
    HORAATU,
    DESCRPROD,
    NOMEVEND,
    CODVENDCAB)
AS
select
m.CodEmp,
m.DataRes,
m.NumRes,
m.NumItem,
m.CodProd,
m.CodVend,
c.CodCond,
c.codmoeda,
f.nomemoeda,
c.codGuia,
c.nomeGuia,
c.CodOper,
e.tpopermov,
c.numresori,
c.dataresori,
m.descrprodgen,
e.descricao as descroper,
d.descricao as descrcond,
c.CodPessoa,
c.NomePessoa,
c.dataprev,
c.horaprev,
c.obs,
c.codsituacao,
g.descricao as descrsit,
m.QtMov,
m.TipoOper,
p.CodBar,
m.QtMovant,
m.VlUnitMov,
m.vlcustomov,
m.vltotdesc,
m.VlTotMov,
m.PerDesc,
m.Usuario,
m.DataAtu,
m.HoraAtu,
CASE
  when p.ingenerico = 'S' then
     m.descrprodgen
  else
     p.desccompleta
END as descrProd,
v.NomeVend as NomeVend,
c.CodVend as CodVendCab
From MOV_RESI m
Left Join MOV_RESC      c on c.codemp =m.codemp
                         and c.datares=m.datares
                         and c.numres =m.numres
Left Join PRD_PRODUTO   p on p.codprod=m.codprod
Left Join CAD_VEND      v on v.codvend=c.codvend
Left Join MOV_OPER      e on e.codoper=c.codoper
Left Join CAD_CONDPGTOC d on d.codcond=c.codcond
Left Join CAD_MOEDA     f on f.codmoeda=c.codmoeda
Left Join TIP_SITMOV    g on g.tpsitmov=m.codsituacao
;



/* View: V_MOV_SAICOND */
CREATE VIEW V_MOV_SAICOND(
    CODEMP,
    DATAMOV,
    NUMMOV,
    NUMITEM,
    CODCLIENTE,
    CODPROD,
    TPOPERMOV,
    CONDPGTO,
    CODMOEDA,
    CODOPER,
    CODSITUACAO,
    CODVEND,
    DESCRPROD,
    DESCRSIT,
    DESCROPER,
    NOMEVEND,
    TIPOVEND,
    VLUNITMOV,
    QTMOV,
    QTDEV,
    QTFATURAR,
    SELECAO)
AS
select
m.CodEmp,
i.datamov,
i.NumMov,
i.NumItem,
d.codcliente,
i.CodProd,
m.TpOperMov,
m.CodCond as condpgto,
m.CodMoeda,
m.CodOper,
i.tp_situacao as codsituacao,
m.CodVend,
c.desccompleta as descrprod,
s.Descricao as DescrSit,
h.Descricao as DescrOper,
v.NomeVend,
v.TipoVend,
COALESCE(i.vlunitario,0) as vlunitmov,
sum(i.qtmov) as qtmov,
sum(i.qtdev) as qtdev,
sum(i.qtfaturar) as qtfaturar,
'F' as selecao
From PRD_QTDECOND I
left Join PRD_PRODUTO   c on c.codprod    = i.codprod
Left Join MOV_SAIC      m on m.codemp     = i.codemp and
                             m.datamov    = i.datamov and
                             m.nummov     = i.nummov
Left Join CAD_VEND      v on v.codvend    = m.codvend
Left Join TIP_SITMOV    s on s.tpsitmov   = m.codsituacao
Left Join CAD_CLIENTE   d on d.codcliente = m.codcliente
Left Join MOV_OPER      h on h.codoper    = m.codoper
group by m.codemp,i.datamov,i.nummov,i.numitem,d.codcliente,i.codprod,m.tpopermov,
m.codcond,m.codmoeda,m.codoper,i.tp_situacao,m.codvend,
c.desccompleta,s.descricao,h.descricao,v.nomevend,v.tipovend,i.vlunitario
;



/* View: V_MOV_SAICSVC */
CREATE VIEW V_MOV_SAICSVC(
    CODEMP,
    DATAMOV,
    NUMMOV,
    CODCLIENTE,
    CODVEND,
    NOMEVEND,
    CODOPER,
    CODCOND,
    DESCROPER,
    SITUACAO,
    CODMOEDA,
    NOMEMOEDA,
    DSOBS,
    NOMECLI,
    DESCRSIT,
    DESCRCOND,
    SELECAO,
    VLTOTMOV)
AS
select
i.CodEmp,
i.DataMov,
i.NumMov,
i.codcliente,
d.codvend,
d.nomevend,
i.CodOper,
d.CodCond,
c.Descricao as DescrOper,
i.Situacao,
i.codmoeda,
mo.nomemoeda,
i.obs as dsObs,
n.nome as nomecli,
s.Descricao as DescrSit,
p.Descricao as DescrCond,
'F' as selecao,
COALESCE(i.VlTotMov,0) as VlTotMov
From MOV_SAICSVC i
Left Join V_MOV_SAIC    d on d.codemp    =i.codemp
                         and d.datamov   =i.datamov
                         and d.nummov    =i.nummov
Left Join CAD_CLIENTE   n on n.codcliente=i.codcliente
Left Join CAD_MOEDA    mo on mo.codmoeda =i.codmoeda
Left Join TIP_SITMOV    s on s.tpsitmov  =i.situacao
Left Join MOV_OPER      c on c.codoper   =i.codoper
Left Join CAD_CONDPGTOC p on p.codcond   =i.codcond
Left Join CAD_VEND      j on j.codvend   =i.codvend
;



/* View: V_MOV_SAIDEV */
CREATE VIEW V_MOV_SAIDEV(
    CODEMP,
    DATAMOV,
    NUMMOV,
    TPOPERMOV,
    CODCOND,
    CODMOEDA,
    CODOPER,
    CODSITUACAO,
    DESCRSIT,
    CODGUIA,
    NOMEGUIA,
    CODCLIENTE,
    NOMECLI,
    CODVEND,
    NOMEVEND,
    CODPROD,
    TIPOVEND,
    CODGRUREGVEN,
    PERCOMIS,
    QTMOV,
    QTDEV,
    QTVENLIQ,
    VLCUSTOMOV,
    VLUNITMOV,
    VLTOTMOV,
    VLTOTVEN,
    VLTOTDEV)
AS
select
m.CodEmp,
m.DataMov,
m.NumMov,
m.TpOperMov,
m.CodCond,
m.CodMoeda,
m.CodOper,
m.CodSituacao,
s.Descricao as DescrSit,
m.CodGuia,
d.nome as nomeGuia,
m.codcliente,
e.nome as nomeCli,
i.CodVend,
v.NomeVend,
i.CodProd,
v.TipoVend,
v.CodgruRegVen,
COALESCE(v.PerComis,0) as PerComis,
COALESCE(i.qtmov,0) as qtmov,
COALESCE(i.qtdev,0) as qtdev,
(COALESCE(i.qtmov,0) - COALESCE(i.qtdev,0)) as qtvenliq,
COALESCE(i.vlcustomov,0) as vlcustomov,
COALESCE(i.vlunitmov,0) as vlunitmov,
COALESCE(i.vltotmov,0) as vltotmov,
CASE
     WHEN i.vltotmov > 0 AND i.qtmov > 0 THEN
        (CAST((CAST(COALESCE(i.vltotmov,0) AS FLOAT) / CAST(COALESCE(i.qtmov,0) AS FLOAT)) AS NUMERIC(12,2)) * (COALESCE(i.qtmov,0) - COALESCE(i.qtdev,0)))
END as vltotven,
CASE
   WHEN i.vltotmov > 0 AND i.qtmov > 0 THEN
        (CAST((CAST(CAST(COALESCE(i.vltotmov,0) AS FLOAT) / CAST(COALESCE(i.qtmov,0) AS FLOAT) AS FLOAT)) * (COALESCE(i.qtdev,0)) AS FLOAT))
END as vltotdev
From MOV_SAII I
Left Join MOV_SAIC      m on m.codemp     =i.codemp
                         and m.datamov    =i.datamov
                         and m.nummov     =i.nummov
Left Join CAD_CLIENTE   d on d.codcliente =m.codguia
Left Join CAD_CLIENTE   e on e.codcliente =m.codcliente
Left Join CAD_VEND      v on v.codvend    =i.codvend
Left Join TIP_SITMOV    s on s.tpsitmov   =m.codsituacao
;



/* View: V_MOV_SAII */
CREATE VIEW V_MOV_SAII(
    CODEMP,
    DATAMOV,
    NUMMOV,
    NUMITEM,
    CODPROD,
    CODGRU,
    CODSUB,
    CODITEM1,
    CODITEM2,
    CODVEND,
    CODBAR,
    TPOPERMOV,
    TIPOOPER,
    TP_SITUACAO,
    DESCRPRODGEN,
    MOEDACOMPRA,
    NOMEMOEDA,
    CODMARCAFOR,
    DESCMARCAFOR,
    USUARIO,
    DATAATU,
    HORAATU,
    DESCRPROD,
    NOMEVEND,
    QTMOV,
    VLUNITMOV,
    VLTOTFRETE,
    VLTOTMOV,
    VLCUSTOMOV,
    VLTOTDESC,
    VLLUCRO,
    VLVENDA,
    VLVENDAATACADO,
    VLVENDAMIN,
    VLPROMOCIONAL,
    PRLUCRO,
    PERDESC)
AS
select
m.CodEmp,
m.DataMov,
m.NumMov,
m.NumItem,
m.CodProd,
p.CodGru,
p.CodSub,
p.CodItem1,
p.CodItem2,
m.CodVend,
p.codbar,
m.TpOperMov,
m.tipooper,
m.Tp_situacao,
m.descrprodgen,
vl.moedacompra,
mo.nomemoeda,
p.codmarcafor,
f.descricao as descmarcafor,
m.Usuario,
m.DataAtu,
m.HoraAtu,
CASE
  when p.ingenerico = 'S' then
     m.descrprodgen
  else
     p.desccompleta
END as descrProd,
v.NomeVend as NomeVend,
cast(COALESCE(m.QtMov,0) as numeric(10,3))      as QtMov,
cast(COALESCE(m.vlUnitMov,0) as numeric(14,4))  as vlUnitMov,
cast(COALESCE(m.vltotfrete,0) as numeric(14,2)) as vlTotFrete,
cast(COALESCE(m.vlTotMov,0) as numeric(14,4))   as vlTotMov,
cast(COALESCE(m.vlCustoMov,0) as numeric(14,4)) as vlCustoMov,
cast(COALESCE(m.vlTotDesc,0) as numeric(14,2))  as vlTotDesc,
cast(COALESCE(m.vltotmov,0) - coalesce(m.vlcustomov*m.qtmov,0) as numeric(14,2)) as vllucro,
cast(COALESCE(vl.vlVenda,0) as numeric(14,2))   as vlVenda,
cast(COALESCE(vl.vlVendaAtacado,0) as numeric(14,2)) as vlVendaAtacado,
cast(COALESCE(vl.vlVendaMin,0) as numeric(14,2)) as vlVendaMin,
cast(COALESCE(vl.vlPromocional,0) as numeric(14,2))  as vlPromocional,
CASE
   WHEN (vl.vlVenda > 0) AND (m.vlCustoMov > 0) THEN
     CAST(((COALESCE(m.vltotmov,0)-COALESCE(m.vlCustoMov*m.qtmov,0))/
           COALESCE(m.vlCustoMov*m.qtmov,0)) * 100 as numeric(10,4))
END as prlucro,
m.PerDesc
From MOV_SAII m
Left Join PRD_PRODUTO p on p.codprod  =m.codprod
Left Join PRD_MARCA   F on f.codmarca =p.codmarcafor
Left Join CAD_VEND    v on v.codvend  =m.codvend
Left Join PRD_VALOR  vl on vl.codemp  =m.codemp
                       and vl.codprod =m.codprod
left Join CAD_MOEDA  mo on mo.codmoeda=vl.moedacompra
;



/* View: V_MOV_SAII2 */
CREATE VIEW V_MOV_SAII2(
    CODEMP,
    DATAMOV,
    NUMMOV,
    NUMITEM,
    CODPROD,
    CODVEND,
    PERDESC,
    CODTERM,
    USUARIO,
    DATAATU,
    HORAATU,
    CODCLIENTE,
    CODCOND,
    CODMOEDA,
    MOEDACOMPRA,
    CODOPER,
    TPOPERMOV,
    DESCRTIPOOPER,
    TIPOOPER,
    CODBAR,
    CODGRUREGVEN,
    CODSITUACAO,
    DESCRPROD,
    DESCRCOMPLETA,
    CODGRU,
    DSSERIE,
    NUMNOTA,
    DATAMOVPED,
    NUMMOVPED,
    DATANOTA,
    NUMTIMBRADO,
    CODSUB,
    NOMEVEND,
    PERCOMIS,
    DESCROPER,
    NOMECLI,
    DESCRCOND,
    NOMEMOEDA,
    SIMBOLO,
    DESCRSIT,
    DESCRICAOGRU,
    DESCRICAOSUB,
    CODMARCAFOR,
    DESCMARCAFOR,
    QTMOV,
    QTDEV,
    VLTOTFRETE,
    VLTOTDESC,
    VLUNITMOV,
    VLUNITBRUTO,
    VLVENDA,
    VLVENDAATACADO,
    VLVENDAMIN,
    VLPROMOCIONAL,
    VLTOTMOV,
    VLCTOUNIT,
    VLCTOTOT,
    VLLUCRO,
    VLTOTCOMIS)
AS
select
i.CodEmp,
i.DataMov,
i.NumMov,
i.NumItem,
i.CodProd,
i.CodVend,
i.PerDesc,
(Select First 1 a.codterm from mov_rec a
        where a.codempmov=i.codemp and
              a.datamov  =i.datamov and
              a.nummov   =i.nummov)
as CodTerm,
i.Usuario,
i.DataAtu,
i.HoraAtu,
m.CodCliente,
m.CodCond,
m.CodMoeda,
pr.moedacompra,
m.CodOper,
i.TpOperMov,
j.descricao as descrtipooper,
o.tipooper,
p.CodBar,
v.CodgruRegVen,
m.CodSituacao,
p.desccompleta as descrProd,
CASE
   when p.ingenerico = 'S' then
      i.descrprodgen
   else 
      p.desccompleta
END as descrCompleta,
p.codgru,
m.dsserie,
m.numnota,
m.datamovped,
m.nummovped,
m.datanota,
m.numtimbrado,
p.codsub,
v.NomeVend as NomeVend,
v.percomis,
o.Descricao as DescrOper,
c.Nome as Nomecli,
cp.Descricao as DescrCond,
mo.NomeMoeda,
mo.Simbolo,
s.Descricao as DescrSit,
pr.descricaogru,
pr.descricaosub,
p.codmarcafor,
f.descricao as descmarcafor,
COALESCE(cast(i.QtMov as numeric(16,4)),0)           as QtMov,
COALESCE(cast(i.QtDev as numeric(16,4)),0)           as QtDev,
COALESCE(cast(i.vltotfrete as numeric(16,4)),0)      as vlTotFrete,
COALESCE(cast(i.vltotdesc  as numeric(16,4)),0)      as vlTotDesc,
COALESCE(cast(i.VlUnitMov as numeric(16,2)),0)       as VlUnitMov,
COALESCE(cast((i.VlUnitMov-i.vltotfrete+i.vltotdesc) as numeric(16,2)),0) as VlUnitBruto,
COALESCE(cast(pr.VlVenda as numeric(16,2)),0)        as VlVenda,
COALESCE(cast(pr.VlVendaAtacado as numeric(16,2)),0) as VlVendaAtacado,
COALESCE(cast(pr.VlVendaMin as numeric(16,2)),0)     as VlVendaMin,
COALESCE(cast(pr.VlPromocional as numeric(16,2)),0)  as VlPromocional,
COALESCE(cast(i.VlTotMov as numeric(16,2)),0)        as VlTotMov,
COALESCE(i.vlcustomov,0) as VlCtoUnit,
COALESCE(cast(i.qtmov as numeric(10,2)),0) * COALESCE(cast(i.vlcustomov as numeric(10,2)),0) as VlCtoTot,
CASE
   WHEN o.tipooper = 'E' THEN
       COALESCE(cast(pr.VlVenda as numeric(16,2)),0) - COALESCE(cast(i.vlunitmov as numeric(16,2)),0)
   WHEN o.tipooper = 'S' THEN
       COALESCE(cast((i.vlunitmov*i.qtmov) as numeric(16,2)),0) - COALESCE(cast((i.vlcustomov*i.qtmov) as numeric(16,2)),0)
END as vlLucro,
CASE 
   WHEN p.unidmedida <> 'SVC' THEN
      CASE
         WHEN v.tipocomis = 'L' THEN
            (COALESCE(cast((i.vlunitmov*i.qtmov) as numeric(16,2)),0) - COALESCE(cast((i.vlcustomov*i.qtmov) as numeric(16,2)),0)) *
             COALESCE(cast(v.percomis as numeric(10,2)),0)/100
         WHEN v.tipocomis = 'B' THEN
            COALESCE((COALESCE(cast(i.VlTotMov as numeric(10,2)),0) * COALESCE(cast(v.percomis as numeric(10,2)),0)/100),0)
      END
   ELSE
      CASE
         WHEN (v.tipocalccomis = 'A') or (v.tipocalccomis = 'S') THEN
             CASE
                WHEN v.tipocomis = 'L' THEN
                   (COALESCE(cast((i.vlunitmov*i.qtmov) as numeric(16,2)),0) - COALESCE(cast((i.vlcustomov*i.qtmov) as numeric(16,2)),0)) *
                    COALESCE(cast(v.percomiscob as numeric(10,2)),0)/100
                WHEN v.tipocomis = 'B' THEN
                   COALESCE((COALESCE(cast(i.VlTotMov as numeric(10,2)),0) * COALESCE(cast(v.percomiscob as numeric(10,2)),0)/100),0)
             END
      END
END as vlTotComis
From MOV_SAII i
Left Join MOV_SAIC       m on m.codemp    =i.codemp
                          and m.datamov   =i.datamov
                          and m.nummov    =i.nummov
Left Join PRD_PRODUTO    p on p.codprod   =i.codprod
Left Join PRD_MARCA      f on f.codmarca  =p.codmarcafor
Left Join V_PRD_PRDQTVL pr on pr.codemp   =i.codemp
                          and pr.codprod  =i.codprod
Left Join CAD_VEND       v on v.codvend   =i.codvend
Left Join MOV_OPER       o on o.codoper   =m.codoper
Left Join CAD_CLIENTE    c on c.codcliente=m.codcliente
Left Join CAD_CONDPGTOC cp on cp.codcond  =m.codcond
Left Join CAD_MOEDA     mo on mo.codmoeda =m.codmoeda
Left Join TIP_SITMOV     s on s.tpsitmov  =m.codsituacao
Left Join TIP_OPERMOV    j on j.tpopermov =m.tpopermov
where i.tpopermov<>24
UNION
select
i.CodEmp,
m.datamovped as datamov,
m.nummovped as nummov,
i.NumItem,
i.CodProd,
i.CodVend,
i.PerDesc,
(Select First 1 a.codterm from mov_rec a
        where a.codempmov=i.codemp and
              a.datamov  =i.datamov and
              a.nummov   =i.nummov)
as CodTerm,
i.Usuario,
i.DataAtu,
i.HoraAtu,
m.CodCliente,
m.CodCond,
m.CodMoeda,
pr.moedacompra,
m.CodOper,
i.TpOperMov,
j.descricao as descrtipooper,
o.tipooper,
p.CodBar,
v.CodgruRegVen,
m.CodSituacao,
p.descricao as descrProd,
CASE
  when p.ingenerico = 'S' then
     i.descrprodgen
  else
     p.desccompleta
END as descrCompleta,
p.codgru,
m.dsserie,
m.numnota,
m.datamovped,
m.nummovped,
m.datanota,
m.numtimbrado,
p.codsub,
v.NomeVend as NomeVend,
v.percomis,
o.Descricao as DescrOper,
c.Nome as Nomecli,
cp.Descricao as DescrCond,
mo.NomeMoeda,
mo.Simbolo,
s.Descricao as DescrSit,
pr.descricaogru,
pr.descricaosub,
p.codmarcafor,
f.descricao as descmarcafor,
COALESCE(cast(i.QtMov as numeric(16,4)),0)           as QtMov,
COALESCE(cast(i.QtDev as numeric(16,4)),0)           as QtDev,
COALESCE(cast(i.vltotfrete as numeric(16,4)),0)      as vlTotFrete,
COALESCE(cast(i.vltotdesc  as numeric(16,4)),0)      as vlTotDesc,
COALESCE(cast(i.VlUnitMov as numeric(16,2)),0)       as VlUnitMov,
COALESCE(cast((i.VlUnitMov-i.vltotfrete+i.vltotdesc) as numeric(16,2)),0) as VlUnitBruto,
COALESCE(cast(pr.VlVenda as numeric(16,2)),0)        as VlVenda,
COALESCE(cast(pr.VlVendaAtacado as numeric(16,2)),0) as VlVendaAtacado,
COALESCE(cast(pr.VlVendaMin as numeric(16,2)),0)     as VlVendaMin,
COALESCE(cast(pr.VlPromocional as numeric(16,2)),0)  as VlPromocional,
COALESCE(cast(i.VlTotMov as numeric(16,2)),0)        as VlTotMov,
COALESCE(i.vlcustomov,0) as VlCtoUnit,
COALESCE(cast(i.qtmov as numeric(10,2)),0) * COALESCE(cast(i.vlcustomov as numeric(10,2)),0) as VlCtoTot,
CASE
   WHEN o.tipooper = 'E' THEN
       COALESCE(cast(pr.VlVenda as numeric(16,2)),0) - COALESCE(cast(i.vlunitmov as numeric(16,2)),0)
   WHEN o.tipooper = 'S' THEN
       COALESCE(cast((i.vlunitmov*i.qtmov) as numeric(16,2)),0) - COALESCE(cast((i.vlcustomov*i.qtmov) as numeric(16,2)),0)
END as vlLucro,
CASE
   WHEN p.unidmedida <> 'SVC' THEN
      CASE
         WHEN v.tipocomis = 'L' THEN
            (COALESCE(cast((i.vlunitmov*i.qtmov) as numeric(16,2)),0) - COALESCE(cast((i.vlcustomov*i.qtmov) as numeric(16,2)),0)) *
             COALESCE(cast(v.percomis as numeric(10,2)),0)/100
         WHEN v.tipocomis = 'B' THEN
            COALESCE((COALESCE(cast(i.VlTotMov as numeric(10,2)),0) * COALESCE(cast(v.percomis as numeric(10,2)),0)/100),0)
      END
   ELSE
      CASE
         WHEN (v.tipocalccomis = 'A') or (v.tipocalccomis = 'S') THEN
             CASE
                WHEN v.tipocomis = 'L' THEN
                   (COALESCE(cast((i.vlunitmov*i.qtmov) as numeric(16,2)),0) - COALESCE(cast((i.vlcustomov*i.qtmov) as numeric(16,2)),0)) *
                    COALESCE(cast(v.percomiscob as numeric(10,2)),0)/100
                WHEN v.tipocomis = 'B' THEN
                   COALESCE((COALESCE(cast(i.VlTotMov as numeric(10,2)),0) * COALESCE(cast(v.percomiscob as numeric(10,2)),0)/100),0)
             END
      END
END as vlTotComis
From MOV_SAII i
Left Join MOV_SAIC       m on m.codemp    =i.codemp
                          and m.datamov   =i.datamov
                          and m.nummov    =i.nummov
Left Join PRD_PRODUTO    p on p.codprod   =i.codprod
Left Join PRD_MARCA      f on f.codmarca  =p.codmarcafor
Left Join V_PRD_PRDQTVL pr on pr.codemp   =i.codemp
                          and pr.codprod  =i.codprod
Left Join CAD_VEND       v on v.codvend   =i.codvend
Left Join MOV_OPER       o on o.codoper   =m.codoper
Left Join CAD_CLIENTE    c on c.codcliente=m.codcliente
Left Join CAD_CONDPGTOC cp on cp.codcond  =m.codcond
Left Join CAD_MOEDA     mo on mo.codmoeda =m.codmoeda
Left Join TIP_SITMOV     s on s.tpsitmov  =m.codsituacao
Left Join TIP_OPERMOV    j on j.tpopermov =m.tpopermov
where i.tpopermov=24
;



/* View: V_MOV_SAIISVC */
CREATE VIEW V_MOV_SAIISVC(
    CODEMP,
    DATAMOV,
    NUMMOV,
    NUMITEM,
    CODPROD,
    CODCLIENTE,
    CODOPER,
    DESCROPER,
    SITUACAO,
    DSOBS,
    DESCRPROD,
    NOMECLIFOR,
    DESCRSIT,
    QTMOV,
    VLUNITMOV,
    VLTOTMOV)
AS
select
i.CodEmp,
i.DataMov,
i.NumMov,
i.NumItem,
i.CodProd,
n.codcliente,
m.CodOper,
c.Descricao as DescrOper,
m.Situacao,
m.obs as dsObs,
j.desccompleta as DescrProd,
n.nome as nomecliFor,
s.Descricao as DescrSit,
COALESCE(i.qtmov,0) as qtmov,
COALESCE(i.VlUnitario,0) as VlUnitMov,
COALESCE(i.VlTotMov,0)   as VlTotMov
From MOV_SAIISVC i
Left Join MOV_SAICSVC    m on m.codemp    =i.codemp
                          and m.datamov   =i.datamov
                          and m.nummov    =i.nummov
Left Join PRD_PRODUTO    j on j.codprod   =i.codprod
Left Join CAD_CLIENTE    n on n.codcliente=m.codcliente
Left Join TIP_SITMOV     s on s.tpsitmov  =m.situacao
Left Join MOV_OPER       c on c.codoper   =m.codoper
;



/* View: V_MOV_SAIMOV */
CREATE VIEW V_MOV_SAIMOV(
    CODEMP,
    DATAMOV,
    NUMMOV,
    CODVEND,
    TPOPERMOV,
    TIPOOPER,
    NUMNOTA,
    DATANOTA,
    DSSERIE,
    NUMTIMBRADO,
    NUMFAT,
    DATAFAT,
    NUMRES,
    DATARES,
    DATAPREV,
    HORAPREV,
    CODCOND,
    DESCRCOND,
    NOMEOPERMOV,
    CODSITUACAO,
    NOMECLIENTE,
    CODCLIENTE,
    USUARIO,
    DATAATU,
    HORAATU,
    NOMEVEND,
    PERCOMIS,
    DESCRSIT,
    CODMOEDA,
    NOMEMOEDA,
    CODOPER,
    DESCROPER,
    VLTOTFATCREDITO,
    QTMOV,
    VLTOTMOV,
    VLTOTCUSTO,
    VLTOTDESC,
    VLTOTVENDA,
    VLLUCRO)
AS
select
m.CodEmp,
m.DataMov,
m.NumMov,
m.CodVend,
m.tpopermov,
m.tipooper,
m.numnota,
m.datanota,
m.dsserie,
m.numtimbrado,
m.numfat,
m.datafat,
m.numres,
m.datares,
m.dataprev,
m.horaprev,
m.codcond,
p.descricao as descrcond,
r.descricao as nomeopermov,
m.CodSituacao,
j.nome as NomeCliente,
m.CodCliente,
m.Usuario,
m.DataAtu,
m.HoraAtu,
v.NomeVend as NomeVend,
v.percomis,
s.Descricao as DescrSit,
m.codmoeda,
(Select b01.nomemoeda from CAD_MOEDA b01
        Where b01.codmoeda =m.codmoeda)
as nomemoeda,
m.codoper,
o.descricao as descroper,
(select sum(y.vlfatura) from fcr_fat y
      where y.codemp=m.codemp and y.codcliente=m.codcliente
        and y.datamov=m.datamov and y.nummov=m.nummov)
as vlTotFatCredito,
(Select cast(Sum(b.qtmov) as numeric(14,3)) from MOV_SAII b
        Where b.codemp   =m.codemp and
              b.datamov  =m.datamov and
              b.nummov   =m.nummov and
              b.tpopermov=m.tpopermov)
as qtmov,
(Select Case
           When m.codmoeda <> 3 then
              Cast(Sum(b1.vltotmov) as numeric(14,2))
           else
              Cast(Sum(b1.vlTotMov) as numeric(14,0))
        end
        from MOV_SAII b1
        Where b1.codemp   =m.codemp and
              b1.datamov  =m.datamov and
              b1.nummov   =m.nummov and
              b1.tpopermov=m.tpopermov)
as vlTotMov,
(Select Case
           When m.codmoeda <> 3 then
              Cast(Sum(b2.vlCustoMov*b2.qtmov) as numeric(14,2))
           else
              Cast(Sum(b2.vlCustoMov*b2.qtmov) as numeric(14,0))
         end
         from MOV_SAII b2
         Where b2.codemp   =m.codemp and
               b2.datamov  =m.datamov and
               b2.nummov   =m.nummov and
               b2.tpopermov=m.tpopermov)
as vlTotCusto,
(Select Case
           When m.codmoeda <> 3 then
              Cast(Sum(b5.vlTotDesc) as numeric(14,2))
           else
              Cast(Sum(b5.vlTotDesc) as numeric(14,0))
        end
        from MOV_SAIC b5
        Where b5.codemp   =m.codemp and
              b5.datamov  =m.datamov and
              b5.nummov   =m.nummov and
              b5.tpopermov=m.tpopermov)
as vlTotDesc,
(Select Case
           When m.codmoeda <> 3 then
              Cast(Sum(b3.vlvenda*b3.qtmov) as numeric(14,2))
           else
              Cast(Sum(b3.vlvenda*b3.qtmov) as numeric(14,0))
        end
        from V_MOV_SAII b3
        Where b3.codemp   =m.codemp and
              b3.datamov  =m.datamov and
              b3.nummov   =m.nummov and
              b3.tpopermov=m.tpopermov)
as vlTotVenda,
(Select Case
          When o.tipooper = 'E' then
             0
          When o.tipooper = 'S' then
             Case
                when m.codmoeda <> 3 then
                   Cast(Sum(b4.vltotmov - (b4.vlcustomov*b4.qtmov)) as numeric(14,2))
                else
                   Cast(Sum(b4.vltotmov - (b4.vlcustomov*b4.qtmov)) as numeric(14,0))
             end
        End
        from MOV_SAII b4
        Where b4.codemp   =m.codemp and
              b4.datamov  =m.datamov and
              b4.nummov   =m.nummov and
              b4.tpopermov=m.tpopermov)
as vlLucro
From V_MOV_SAIC m
Left Join MOV_OPER      o on o.codoper   =m.codoper
Left Join CAD_CONDPGTOC p on p.codcond   =m.codcond
Left Join CAD_VEND      v on v.codvend   =m.codvend
Left Join CAD_CLIENTE   j on j.codcliente=m.codcliente
Left Join TIP_SITMOV    s on s.tpsitmov  =m.codsituacao
Left Join TIP_OPERMOV   r on r.tpopermov =m.tpopermov
;



/* View: V_MOV_SAIREMISC */
CREATE VIEW V_MOV_SAIREMISC(
    CODEMP,
    DATAMOV,
    NUMMOV,
    NUMREMISSAO,
    CODCLIDEST,
    NOMECLIDEST,
    NOMECONDUTOR,
    CIDADECLIDEST,
    RUCCLIDEST,
    DOCCONDUTOR,
    DSMOTIVO,
    CODOPER,
    DESCROPER,
    CODSITUACAO,
    DESCRSIT,
    CODMOEDA,
    NOMEMOEDA,
    DTINITRANS,
    DTFIMTRANS,
    PLACAVEIC,
    DSMARCAVEIC,
    SELECAO,
    QTMOV,
    VLTOTMOV)
AS
Select
i.CodEmp,
i.DataMov,
i.NumMov,
i.numremissao,
i.codclidest as codclidest,
a.razaosocial as nomeclidest,
i.nomecondutor,
a.nomecidade as cidadeclidest,
a.docfiscal as rucclidest,
i.doccondutor,
i.dsmotivo,
i.CodOper,
c.Descricao as DescrOper,
i.CodSituacao,
s.Descricao as DescrSit,
i.codmoeda,
mo.nomemoeda,
i.dtinitrans,
i.dtfimtrans,
i.placaveic,
i.dsmarcaveic,
'F' as selecao,
COALESCE(i.QtMov,0) as QtMov,
COALESCE(i.VlTotMov,0) as VlTotMov
From MOV_SAIC i
Left Join V_CAD_CLIENTE   a on a.codcliente=i.codcliente
Left Join CAD_MOEDA    mo on mo.codmoeda =i.codmoeda
Left Join TIP_SITMOV    s on s.tpsitmov  =i.codsituacao
Left Join MOV_OPER      c on c.codoper   =i.codoper
Left Join CAD_CONDPGTOC p on p.codcond   =i.codcond
Left Join CAD_VEND      j on j.codvend   =i.codvend
where i.tpopermov=28
;



/* View: V_MOV_SAIREMISI */
CREATE VIEW V_MOV_SAIREMISI(
    CODEMP,
    DATAMOV,
    NUMMOV,
    NUMITEM,
    CODPROD,
    DESCCOMPLETA,
    QTMOV,
    VLCUSTOMOV,
    VLUNITMOV,
    VLTOTMOV)
AS
Select
i.CodEmp,
i.DataMov,
i.NumMov,
i.numitem,
i.codprod,
a.desccompleta,
COALESCE(i.QtMov,0) as QtMov,
COALESCE(i.vlcustomov,0) as VlCustoMov,
COALESCE(i.vlunitmov,0) as vlUnitMov,
COALESCE(i.VlTotMov,0) as VlTotMov
From MOV_SAII i
Left Join PRD_PRODUTO  a on a.codprod=i.codprod
where i.tpopermov=28
;



/* View: V_MOV_SAIRES */
CREATE VIEW V_MOV_SAIRES(
    CODEMP,
    DATAMOV,
    NUMMOV,
    CODVEND,
    CODSITUACAO,
    CODCLIENTE,
    NOMECLIENTE,
    USUARIO,
    DATAATU,
    HORAATU,
    NOMEVEND,
    DESCRSIT,
    QTMOV,
    VLTOTMOV)
AS
select
m.CodEmp,
m.Datamov,
m.Nummov,
m.CodVend,
j.razaosocial as nomecliente,
m.CodSituacao,
m.Codcliente,
m.Usuario,
m.DataAtu,
m.HoraAtu,
v.NomeVend as NomeVend,
s.Descricao as DescrSit,
Sum(COALESCE(i.qtmov,0)) as qtmov,
Sum(COALESCE(i.vltotmov,0)) as vltotmov
From MOV_SAIC m
Left Join CAD_VEND      v on v.codvend   =m.codvend
Left Join CAD_CLIENTE   j on j.codcliente=m.codcliente
Left Join TIP_SITMOV    s on s.tpsitmov  =m.codsituacao
Left Join MOV_SAII      I on i.codemp    =m.codemp
                    and I.datamov=m.datamov
                    and I.nummov=m.nummov
Group by m.CodEmp, m.DataMov, m.NumMov, m.CodVend,
m.CodSituacao,m.CodCliente,j.razaosocial,m.Usuario,m.DataAtu,m.HoraAtu,
v.NomeVend,s.Descricao
;
;



/* View: V_MOV_SAIVEIC */
CREATE VIEW V_MOV_SAIVEIC(
    CODEMP,
    DATAMOV,
    NUMMOV,
    NUMITEM,
    CODPROD,
    CODGRU,
    CODSUB,
    CODITEM1,
    CODITEM2,
    CODVEND,
    CODCLIENTE,
    DSCLIENTE,
    DOCIDENTIDADE,
    DOCFISCAL,
    NACIONALIDADE,
    NOMECIDADE,
    ESTADOCIVIL,
    QTMOV,
    TPOPERMOV,
    CODOPER,
    DSOPERACAO,
    CODCOND,
    DSCONDPGTO,
    TP_SITUACAO,
    MOEDACOMPRA,
    DSMOEDACOMPRA,
    MOEDAVENDA,
    DSMOEDAVENDA,
    USUARIO,
    DATAATU,
    HORAATU,
    DESCRPROD,
    NOMEVEND,
    DSCHASSI,
    DSMOTOR,
    CODMARCA,
    DSMARCA,
    CODMARCAFOR,
    DSMARCAFOR,
    CODMODELO,
    DSMODELO,
    ANOFABR,
    ANOMODELO,
    CODCOR,
    DSCOR,
    TPCOMBUSTIVEL,
    INNOVOUSADO,
    DSTIPOCOMBUSTIVEL,
    PLACAVEICULO,
    TPVEICULO,
    VLUNITMOV,
    VLTOTMOV,
    VLCUSTOMOV,
    PERDESC,
    VLTOTDESC,
    SELECAO)
AS
select
m.CodEmp,
m.DataMov,
m.NumMov,
m.NumItem,
m.CodProd,
p.CodGru,
p.CodSub,
p.CodItem1,
p.CodItem2,
m.CodVend,
b.codcliente,
g.nome as dscliente,
g.docidentidade,
g.docfiscal,
g.nacionalidade,
k.nomeuf as nomecidade,
g.estadocivil,
m.QtMov,
m.TpOperMov,
b.codoper,
j.descricao as dsoperacao,
b.codcond,
h.descricao as dscondpgto,
m.Tp_situacao,
vl.moedacompra,
moc.nomemoeda as dsmoedacompra,
b.codmoeda as moedavenda,
mov.nomemoeda as dsmoedavenda,
m.Usuario,
m.DataAtu,
m.HoraAtu,
p.descricao as descrProd,
v.NomeVend as NomeVend,
P.dschassi,
P.dsmotor,
P.codmarca,
c.descricao as dsmarca,
P.codmarcafor,
cl.descricao as dsmarcafor,
p.codmodelo,
d.descricao as dsmodelo,
p.anofabr,
p.anomodelo,
p.codcor,
e.descricao as dscor,
p.tpcombustivel,
p.innovousado,
f.descricao as dstipocombustivel,
p.placaveiculo,
p.tpveiculo,
m.VlUnitMov,
m.VlTotMov,
m.VlCustoMov,
m.PerDesc,
m.VltotDesc,
'F' as selecao
From MOV_SAII m
Left Join MOV_SAIC        b on b.codemp       =m.codemp
                           and b.datamov      =m.datamov
                           and b.nummov       =m.nummov
Left Join PRD_PRODUTO     p on  p.codprod     =m.codprod
Left Join PRD_VALOR      vl on vl.codemp      =m.codemp
                           and vl.codprod     =m.codprod
left Join CAD_CONDPGTOC   h on h.codcond      =b.codcond
left Join MOV_OPER        j on j.codoper      =b.codoper
Left Join CAD_CLIENTE     g on g.codcliente   =b.codcliente
Left Join V_CAD_CIDADE    k on k.codcidade    =g.codcidade
Left Join CAD_VEND        v on v.codvend      =m.codvend
Left Join PRD_MARCA       c on c.codmarca     =p.codmarca
Left Join PRD_MARCA       cl on cl.codmarca   =p.codmarcafor
Left Join PRD_MODELO      d on d.codmarca     =p.codmarca
                           and d.codmodelo    =p.codmodelo
Left Join PRD_COR         e on e.codcor       =p.codcor
Left Join TIP_COMBUSTIVEL f on f.tpcombustivel =p.tpcombustivel
left Join CAD_MOEDA      moc on moc.codmoeda   =vl.moedacompra
left Join CAD_MOEDA      mov on mov.codmoeda   =b.codmoeda
;



/* View: V_MOV_SAIVEND */
CREATE VIEW V_MOV_SAIVEND(
    CODEMP,
    DATAMOV,
    NUMMOV,
    TPOPERMOV,
    TIPOOPER,
    CODCOND,
    DESCRCOND,
    MOEDACOMPRA,
    CODMOEDA,
    NOMEMOEDA,
    SIMBOLO,
    CODOPER,
    DESCROPER,
    CODSITUACAO,
    DESCRSIT,
    CODVEND,
    NOMEVEND,
    CODGUIA,
    NOMEGUIA,
    CODCLIENTE,
    NOMECLI,
    CODMARCA,
    DESCMARCA,
    NUMNOTA,
    TIPOVEND,
    TIPOCOMIS,
    CODGRUREGVEN,
    PERCOMIS,
    NUMRES,
    DATARES,
    SELECAO,
    QTMOV,
    QTDEV,
    QTVENLIQ,
    VLTOTDESCMOV,
    VLTOTBRUTOMOV,
    VLTOTMOV,
    VLTOTCUSTOMOV,
    VLTOTLUCROMOV,
    VLTOTCOMISMOV)
AS
select
m.CodEmp,
m.DataMov,
m.NumMov,
mp.TpOperMov,
m.TipoOper,
mp.CodCond,
p.Descricao as DescrCond,
pr.moedacompra,
mp.CodMoeda,
mp.NomeMoeda,
mo.Simbolo,
mp.CodOper,
o.Descricao as DescrOper,
mp.CodSituacao,
mp.DescrSit,
mp.CodVend,
j.NomeVend,
mp.CodGuia,
mp.NomeGuia,
mp.CodCliente,
mp.NomeCli,
q.codmarcafor as codmarca,
c.descricao as descmarca,
mp.NumNota,
j.TipoVend,
j.TipoComis,
j.CodgruRegVen,
j.PerComis,
mp.NumRes,
mp.DataRes,
'F' as Selecao,
cast(Sum(m.qtmov) as numeric(10,3)) as qtmov,
cast(Sum(m.qtdev) as numeric(10,3)) as qtdev,
cast(Sum(m.qtmov - m.qtdev) as numeric(10,3)) as qtvenliq,
Cast(Sum(m.vltotdesc) as numeric(14,2)) as vlTotDescMov,
Cast(Sum(m.vltotmov) as numeric(14,2)) as vlTotbrutoMov,
Cast(Sum(m.vltotmov) as numeric(14,2)) as vlTotmov,
Cast(Sum(
   CASE
     WHEN m.vlcustomov > 0 and
          m.qtmov > 0 THEN
          (m.vlcustomov * m.qtmov)
     ELSE 0
   END
) as numeric(14,2)) as vlTotcustoMov,
Cast(Sum(
   CASE
     WHEN m.vlcustomov > 0 and
          m.qtmov > 0 THEN
        m.vltotmov - (m.vlcustomov*m.qtmov)
     ELSE 0
   END
) as numeric(14,2)) as vlTotlucroMov,
Cast(Sum(
    CASE
       WHEN q.unidmedida <> 'SVC' and j.percomis > 0 THEN
          CASE
             WHEN j.tipocomis = 'L' THEN
                (m.vltotmov - (m.vlcustomov*m.qtmov)) * j.percomis / 100
             WHEN j.tipocomis = 'B' THEN
                m.VlTotMov * j.percomis / 100
          END
       ELSE
          CASE
             WHEN ((j.tipocalccomis = 'A') or (j.tipocalccomis = 'S')) and (j.percomis > 0) THEN
                 CASE
                    WHEN j.tipocomis = 'L' THEN
                      ( m.vltotmov - (m.vlcustomov*m.qtmov)) * j.percomiscob / 100
                    WHEN j.tipocomis = 'B' THEN
                       m.VlTotMov*j.percomiscob / 100
                 END
          END
    END
) as numeric(14,2)) as vlTotComisMov
From MOV_SAII m
Left Join V_MOV_SAIC   mp on mp.codemp  =m.codemp
                         and mp.datamov =m.datamov
                         and mp.nummov  =m.nummov
Left Join PRD_PRODUTO   q on q.codprod  =m.codprod
Left Join MOV_OPER      o on o.codoper  =mp.codoper
Left Join PRD_MARCA     c on c.codmarca =q.codmarcafor
Left Join CAD_VEND      j on j.codvend  =mp.codvend
Left Join CAD_CONDPGTOC p on p.codcond  =mp.codcond
Left Join PRD_VALOR    pr on pr.codemp  =m.codemp
                         and pr.codprod =m.codprod
Left Join CAD_MOEDA    mo on mo.codmoeda=mp.codmoeda
Group by m.CodEmp,m.DataMov,m.NumMov,mp.TpOperMov,m.TipoOper,mp.CodCond,p.Descricao,mp.CodMoeda,pr.moedacompra,
mp.NomeMoeda,mo.Simbolo,mp.CodOper,o.Descricao,mp.CodSituacao,mp.DescrSit,mp.CodVend,
j.NomeVend,mp.CodGuia,mp.NomeGuia,mp.CodCliente,mp.NomeCli,q.codmarcafor,c.descricao,mp.NumNota,j.TipoVend,j.TipoComis,j.CodgruRegVen,
j.PerComis,mp.NumRes,mp.DataRes
;



/* View: V_PRD_KARDEX */
CREATE VIEW V_PRD_KARDEX(
    CODEMP,
    CODPROD,
    DESCCOMPLETA,
    CODOPERSALDO,
    DESCTIPOPERSALDO,
    DATAMOV,
    NRSEQ,
    CODHISTORICO,
    DESCHISTORICO,
    TPHISTORICO,
    INESTORNO,
    TPDCTOORIGEM,
    DESCTIPDOC,
    CODEMPORIGEM,
    NUMDOCORIGEM,
    DATADOCORIGEM,
    QTMOVIMENTADA,
    CODOPER,
    DESCOPER,
    CODVEND,
    NOMEVEND,
    COMPONENTE,
    TPVALOR,
    DESCTIPVALOR,
    VLUNITARIO,
    USUARIO,
    DATAATU,
    HORAATU)
AS
Select
m.codemp,
m.codprod,
b.desccompleta,
m.codopersaldo,
g.descricao as desctipopersaldo,
m.datamov,
m.nrseq,
m.codhistorico,
c.descricao as deschistorico,
c.tphistorico,
m.inestorno,
m.tpdctoorigem,
d.descricao as desctipdoc,
m.codemporigem,
m.numdocorigem,
m.datadocorigem,
m.qtmovimentada,
m.codoper,
e.descricao as descoper,
h.codvend,
j.nomevend,
m.componente,
m.tpvalor,
f.descricao as desctipvalor,
m.vlunitario,
m.usuario,
m.dataatu,
m.horaatu
from PRD_KARDEX m
left Join MOV_SAIC    h    on h.codemp =m.codemp
                         and  h.datamov=m.datamov
                         and  h.nummov =m.numdocorigem
Left Join CAD_VEND    j    on j.codvend=h.codvend
Left Join PRD_PRODUTO b    on b.codprod=m.codprod
Left Join PRD_HISTKARDEX c on c.codhistorico=m.codhistorico
Left Join TIP_OPERMOV d    on d.tpopermov=m.tpdctoorigem
Left Join MOV_OPER    e    on e.codoper=m.codoper
Left Join TIP_VLVENDA f    on f.tpvalor=m.tpvalor
Left Join TIP_ESTOQUE g    on g.tpest=m.codopersaldo
;



/* View: V_PRD_PRDVL */
CREATE VIEW V_PRD_PRDVL(
    CODEMP,
    CODGRU,
    CODSUB,
    CODITEM1,
    CODITEM2,
    CODPROD,
    DESCITEM2,
    DESCRICAO,
    DESCCOMPLETA,
    UNIDMEDIDA,
    IMPOSTO,
    CODBAR,
    DESCRICAOGRU,
    DESCCOMPLETAGRU,
    NIVELG,
    DESCRICAOSUB,
    DESCCOMPLETASUB,
    NIVELS,
    CODGRUSUB,
    CODGRUSUBITEM,
    NIVELI,
