    VLVENDAMIN,
    VLVENDAVAREJOINI,
    VLVENDAVAREJOFIM,
    MARGEM,
    MARGEM1,
    MARGEM2,
    MARGEM3,
    MARGEM4,
    MARGEM5,
    PERCDESCMAX,
    SELECAO)
AS
Select
