e.Imposto,
e.CodBar,
e.DescricaoGru,
e.DescCompletaGru,
e.NivelG,
e.DescricaoSub,
e.DescCompletaSub,
e.NivelS,
e.CodGruSub,
e.CodGruSubItem,
i.Descnivel as NivelI,
v.moedacompra,
m.nomemoeda,
c.valor,
d.inativo,
n.qtfisica,
n.qtreserva,
d.codsitprod,
f.qttempo,
f.corsimbolo,
n.dtultvenda,
n.dtultcompra,
d.ingenerico,
d.inmateriaprima,
COALESCE(v.VlCtoUltComp,0) as VlCtoUltComp,
CASE
    WHEN v.moedacompra <> b.codmoeda THEN
      CASE
        WHEN C.tipocalc = 'M' and b.codmoeda <> 3 THEN
            COALESCE(CAST((v.VlVenda*c.valor) as numeric(14,4)),0)
        WHEN C.tipocalc = 'D' and b.codmoeda <> 3 THEN
            COALESCE(CAST((v.VlVenda/c.valor) as numeric(14,4)),0)
        WHEN C.tipocalc = 'M' and b.codmoeda = 3 THEN
            COALESCE(CAST((v.VlVenda*c.valor) as numeric(14,0)),0)
        WHEN C.tipocalc = 'D' and b.codmoeda = 3 THEN
            COALESCE(CAST((v.VlVenda/c.valor) as numeric(14,0)),0)
      END
    ELSE
        COALESCE(CAST(v.VlVenda as numeric(14,3)),0)
END as VlVenda,
CASE
    WHEN v.moedacompra <> b.codmoeda THEN
      CASE
        WHEN C.tipocalc = 'M' and b.codmoeda <> 3 THEN
            COALESCE(CAST((v.VlVendaAtacado*c.valor) as numeric(14,4)),0)
        WHEN C.tipocalc = 'D' and b.codmoeda <> 3 THEN
            COALESCE(CAST((v.VlVendaAtacado/c.valor) as numeric(14,4)),0)
        WHEN C.tipocalc = 'M' and b.codmoeda = 3 THEN
            COALESCE(CAST((v.VlVendaAtacado*c.valor) as numeric(14,0)),0)
        WHEN C.tipocalc = 'D' and b.codmoeda = 3 THEN
            COALESCE(CAST((v.VlVendaAtacado/c.valor) as numeric(14,0)),0)
      END
    ELSE
       COALESCE(CAST(v.VlVendaAtacado as numeric(14,3)),0)
END as VlVendaAtacado,
CASE
    WHEN v.moedacompra <> b.codmoeda THEN
      CASE
        WHEN C.tipocalc = 'M' and b.codmoeda <> 3 THEN
            COALESCE(CAST((v.VlPromocional*c.valor) as numeric(14,4)),0)
        WHEN C.tipocalc = 'D' and b.codmoeda <> 3 THEN
            COALESCE(CAST((v.VlPromocional/c.valor) as numeric(14,4)),0)
        WHEN C.tipocalc = 'M' and b.codmoeda = 3 THEN
            COALESCE(CAST((v.VlPromocional*c.valor) as numeric(14,0)),0)
        WHEN C.tipocalc = 'D' and b.codmoeda = 3 THEN
            COALESCE(CAST((v.VlPromocional/c.valor) as numeric(14,0)),0)
      END
    ELSE
      COALESCE(CAST(v.VlPromocional as numeric(14,3)),0)
END as VlPromocional,
CASE
    WHEN v.moedacompra <> b.codmoeda THEN
      CASE
        WHEN C.tipocalc = 'M' and b.codmoeda <> 3 THEN
            COALESCE(CAST((v.VlVendaMin*c.valor) as numeric(14,4)),0)
        WHEN C.tipocalc = 'D' and b.codmoeda <> 3 THEN
            COALESCE(CAST((v.VlVendaMin/c.valor) as numeric(14,4)),0)
        WHEN C.tipocalc = 'M' and b.codmoeda = 3 THEN
            COALESCE(CAST((v.VlVendaMin*c.valor) as numeric(14,0)),0)
        WHEN C.tipocalc = 'D' and b.codmoeda = 3 THEN
            COALESCE(CAST((v.VlVendaMin/c.valor) as numeric(14,0)),0)
      END
    ELSE
       COALESCE(CAST(v.VlVendaMin as numeric(14,3)),0)
END as VlVendaMin,
CASE
    WHEN v.moedacompra <> b.codmoeda THEN
      CASE
        WHEN C.tipocalc = 'M' and b.codmoeda <> 3 THEN
            COALESCE(CAST((v.VlVarejoIni*c.valor) as numeric(14,4)),0)
        WHEN C.tipocalc = 'D' and b.codmoeda <> 3 THEN
            COALESCE(CAST((v.VlVarejoIni/c.valor) as numeric(14,4)),0)
        WHEN C.tipocalc = 'M' and b.codmoeda = 3 THEN
            COALESCE(CAST((v.VlVarejoIni*c.valor) as numeric(14,0)),0)
        WHEN C.tipocalc = 'D' and b.codmoeda = 3 THEN
            COALESCE(CAST((v.VlVarejoIni/c.valor) as numeric(14,0)),0)
      END
    ELSE
       COALESCE(CAST(v.VlVarejoIni as numeric(14,3)),0)
END as VlVendaVarejoIni,
CASE
    WHEN v.moedacompra <> b.codmoeda THEN
      CASE
         WHEN C.tipocalc = 'M' and b.codmoeda <> 3 THEN
            COALESCE(CAST((v.VlVarejoFim*c.valor) as numeric(14,4)),0)
         WHEN C.tipocalc = 'D' and b.codmoeda <> 3 THEN
            COALESCE(CAST((v.VlVarejoFim/c.valor) as numeric(14,4)),0)
         WHEN C.tipocalc = 'M' and b.codmoeda = 3 THEN
            COALESCE(CAST((v.VlVarejoFim*c.valor) as numeric(14,0)),0)
         WHEN C.tipocalc = 'D' and b.codmoeda = 3 THEN
            COALESCE(CAST((v.VlVarejoFim/c.valor) as numeric(14,0)),0)
      END
    ELSE
       COALESCE(CAST(v.VlVarejoFim  as numeric(14,3)),0)
END as VlVendaVarejoFim,
COALESCE(v.margem,0)  as margem,
COALESCE(v.margem1,0) as margem1,
COALESCE(v.margem2,0) as margem2,
COALESCE(v.margem3,0) as margem3,
COALESCE(v.prmargvarini,0) as margem4,
COALESCE(v.prmargvarfim,0) as margem5,
COALESCE(v.PercDescMax,0) as PercDescMax,
'F' as selecao
From V_PRD_PRDEMP E
Left Join PRD_PRODUTO D  on d.codprod      =e.codprod
Left Join PRD_ITEM1 I    on i.coditem1     =e.coditem1
Left Join PRD_VALOR V    on v.codemp       =e.codemp
                        and v.codprod      =e.codprod
Left Join PRD_QTDE  N    on n.codemp       =e.codemp
                        and n.codprod      =v.codprod
Left Join CAD_MOEDA M    on m.codmoeda     =v.moedacompra
Left Join ADM_PARAM B    on b.codemp       =e.codemp
Left Join TIP_SITPROD F  on f.codsitprod   =d.codsitprod
Left Join CAD_COTACAO C  on c.codemp       =v.codemp
                         and c.codmoedaori =v.moedacompra
                         and c.codmoedaconv=b.codmoeda
                         and c.datacotacao =b.datasistema
;



/* View: V_PRD_LISTAPROMO */
CREATE VIEW V_PRD_LISTAPROMO(
    CODEMP,
    CODLISTA,
    CODPROD,
    TIPOLISTA,
    DESCTIPOLISTA,
    CODGRU,
    CODSUB,
    CODITEM1,
    CODITEM2,
    DESCITEM2,
    DESCRICAO,
    DESCCOMPLETA,
    DESCRICAOGRU,
    DESCCOMPLETAGRU,
    DESCRICAOSUB,
    DESCCOMPLETASUB,
    CODGRUSUB,
    CODGRUSUBITEM,
    UNIDMEDIDA,
    IMPOSTO,
    CODBAR,
    SITUACAO,
    DESCSITUACAO,
    DTINICIO,
    DTFIM,
    DIASEMANA,
    DESCDIASEMANA,
    MOEDACOMPRA,
    NOMEMOEDA,
    CODSITPROD,
    QTFISICA,
    QTRESERVA,
    VLVENDA,
    VLCTOULTCOMP,
    MARGEM,
    SELECAO)
AS
Select
e.CodEmp,
e.CodLista,
e.CodProd,
e.TipoLista,
case e.TipoLista
   when '1' then 'POR PERIODO'
   else 'SEMANAL'
end as descTipoLista,
d.CodGru,
d.CodSub,
d.CodItem1,
d.CodItem2,
d.DescItem2,
d.Descricao,
d.DescCompleta,
d.DescricaoGru,
d.DescCompletaGru,
d.DescricaoSub,
d.DescCompletaSub,
d.CodGruSub,
d.CodGruSubItem,
d.UnidMedida,
d.Imposto,
d.CodBar,
e.situacao,
case e.situacao
   when '1' then 'ATIVA'
   else 'INATIVA'
end as descsituacao,
e.dtinicio,
e.dtfim,
e.diasemana,
case e.diasemana
   when 1 then 'DOMINGO'
   when 2 then 'LUNES'
   when 3 then 'MARTES'
   when 4 then 'MIERCOLES'
   when 5 then 'JUEVES'
   when 6 then 'VIERNES'
   when 7 then 'SABADO'
end as descDiaSemana,
d.moedacompra,
m.nomemoeda,
d.codsitprod,
d.qtfisica,
d.qtreserva,
CASE
   WHEN d.moedacompra <> c.codmoeda THEN
      CASE
         WHEN f.tipocalc = 'M' THEN
           COALESCE(CAST((e.vlvenda*f.valor) as numeric(14,3)),0)
         ELSE
           COALESCE(CAST((e.vlvenda/f.valor) as numeric(14,3)),0)
      END
   ELSE
      COALESCE(CAST(e.vlvenda as numeric(14,3)),0)
END as VlVenda,
COALESCE(d.VlCtoUltComp,0) as VlCtoUltComp,
COALESCE(e.margem,0) as margem,
'F' as selecao
From PRD_VALORPROMO e
Left Join V_PRD_PRDVL d  on d.codprod     =e.codprod
Left Join CAD_MOEDA   m  on m.codmoeda    =d.moedacompra
Left Join ADM_PARAM   c  on c.codemp      =e.codemp
Left Join CAD_COTACAO f  on f.codemp      =e.codemp
                        and f.codmoedaori =d.moedacompra
                        and f.codmoedaconv=c.codmoeda
                        and f.datacotacao =c.datasistema
;



/* View: V_PRD_LOTE */
CREATE VIEW V_PRD_LOTE(
    CODEMP,
    CODPROD,
    CODLOTE,
    CODGRU,
    CODSUB,
    CODITEM1,
    CODITEM2,
    DESCITEM2,
    DESCRICAO,
    DESCCOMPLETA,
    UNIDMEDIDA,
    DSLOTE,
    DATAVENCTO,
    SITUACAO,
    DSSITUACAO,
    CODBAR,
    DESCCOMPLETAGRU,
    DESCCOMPLETASUB,
    QTFISICA)
AS
Select
e.CodEmp,
e.CodProd,
i.CodLote,
e.CodGru,
e.CodSub,
e.CodItem1,
e.CodItem2,
e.DescItem2,
e.Descricao,
e.DescCompleta,
e.UnidMedida,
i.DsLote,
i.DataVencto,
i.Situacao,
Case 
   When i.Situacao = 'A' then
       'Ativo'
   else 
       'Inativo'
End as DsSituacao,
e.Codbar,
e.DescCompletaGru,
e.DescCompletaSub,
COALESCE(i.QtFisica,0) as QtFisica
From V_PRD_PRDEMP e
Left Join PRD_LOTE i on i.codprod=e.codprod
;



/* View: V_PRD_MOVTANQUE */
CREATE VIEW V_PRD_MOVTANQUE(
    CODEMP,
    CODGRU,
    CODSUB,
    CODITEM1,
    CODITEM2,
    CODPROD,
    CODTANQUE,
    DTCONTAGEM,
    NUMITEMCONT,
    USUARIO,
    DATAATU,
    HORAATU,
    DESCITEM2,
    DESCRICAO,
    DESCRCOMPLETA,
    UNIDMEDIDA,
    IMPOSTO,
    DESCRICAOGRU,
    DESCCOMPLETAGRU,
    DESCRICAOSUB,
    DESCCOMPLETASUB,
    CODGRUSUB,
    CODGRUSUBITEM,
    QTSALDOANT,
    QTABERTURA,
    QTFECHAMENTO,
    QTSALDOATU,
    VLVENDA,
    VLVENDAMIN,
    VLCTOULTCOMP,
    VLPROMOCIONAL,
    VLVENDAATACADO)
AS
select
e.CodEmp,
v.CodGru,
v.CodSub,
v.CodItem1,
v.CodItem2,
d.CodProd,
e.codtanque,
e.DtContagem,
e.NumItemCont,
e.usuario,
e.dataatu,
e.horaatu,
v.DescItem2,
v.Descricao,
v.DescCompleta as descrcompleta,
v.UnidMedida,
v.Imposto,
v.DescricaoGru,
v.DescCompletaGru,
v.DescricaoSub,
v.DescCompletaSub,
v.CodGruSub,
v.CodGruSubItem,
COALESCE(e.QtSaldoAnt,0)   as QtSaldoAnt,
COALESCE(e.QtAbertura,0)   as QtAbertura,
COALESCE(e.QtFechamento,0) as QtFechamento,
COALESCE(e.QtSaldoAtu,0)   as QtSaldoAtu,
COALESCE(cast(v.VlVenda as numeric(16,2)),0) as VlVenda,
COALESCE(cast(v.VlVendaMin as numeric(16,2)),0) as VlVendaMin,
COALESCE(cast(v.VlCtoUltComp as numeric(16,2)),0) as VlCtoUltComp,
COALESCE(cast(v.VlPromocional as numeric(16,2)),0) as VlPromocional,
COALESCE(cast(v.VlVendaAtacado as numeric(16,2)),0) as VlVendaAtacado
From PRD_MOVTANQUE E
left Join PRD_TANQUES D on d.codemp   =e.codemp
                       and d.codtanque=e.codtanque
Left Join V_PRD_PRDVL V on v.codemp   =e.codemp
                       and v.codprod  =d.codprod
;



/* View: V_PRD_PLANCUSTO */
CREATE VIEW V_PRD_PLANCUSTO(
