cast(coalesce(f.prlucro,0) as numeric(10,3)) as PrLucro,
cast(coalesce(f.prcusto,0) as numeric(14,2)) as PrCusto,
cast(coalesce(f.vllucro,0) as numeric(14,2)) as VlLucro
From PRD_PLANCUSTO F
Left Join PRD_CUSTDESP E on e.codCusto=f.codCusto
;



/* View: V_PRD_PRDQTDE */
CREATE VIEW V_PRD_PRDQTDE(
    CODEMP,
    CODPROD,
    CODGRU,
    CODSUB,
    CODITEM1,
    CODITEM2,
    DESCITEM2,
    DESCRICAO,
    DESCCOMPLETA,
    UNIDMEDIDA,
    CODBAR,
    CODNIVEL,
    NIVELG,
    NIVELS,
    NIVELI,
    QTFISICA,
    QTEMPENHADA,
    QTRESERVA,
    QTVENDIDA,
    QTRMA,
    QTTERCEIRO,
    QTMINIMA,
    QTMAXIMA,
    QTFRACIONADA,
    INATIVO,
    QTTOTAL)
AS
Select
q.CodEmp,
q.CodProd,
p.CodGru,
p.CodSub,
p.CodItem1,
p.CodItem2,
p.DescItem2,
p.Descricao,
p.DescCompleta,
p.UnidMedida,
p.CodBar,
(p.CodGru ||'.'|| p.CodSub ||'.'|| p.CodItem1 ||'.'|| p.CodItem2) as CodNivel,
g.Descnivel as NivelG,
s.Descnivel as NivelS,
i.Descnivel as NivelI,
COALESCE(q.QtFisica,0) as QtFisica,
COALESCE(q.QtEmpenhada,0) as QtEmpenhada,
COALESCE(q.QtReserva,0) as QtReserva,
COALESCE(q.QtVendida,0) as QtVendida,
COALESCE(q.QtRma,0) as QtRma,
COALESCE(q.QtTerceiro,0) as QtTerceiro,
COALESCE(q.QtMinima,0) as QtMinima,
COALESCE(q.QtMaxima,0) as QtMaxima,
q.QtFracionada,
q.Inativo,
(COALESCE((COALESCE(q.QtFisica,0) + COALESCE(q.QtEmpenhada,0) + COALESCE(q.QtReserva,0) + COALESCE(q.QtVendida,0) + COALESCE(q.QtRma,0)),0)) as QtTotal
From PRD_QTDE Q
Left Join PRD_PRODUTO P  on p.codprod=q.codprod
Left Join PRD_GRUPO G    on g.codgru=p.codgru
Left Join PRD_SUBGRUPO S on s.codgru=p.codgru and s.codsub=p.codsub
Left Join PRD_ITEM1 I    on i.coditem1=p.coditem1
;



