COALESCE(f.QtTerceiro,0) as QtTerceiro,
COALESCE(cast(c.VlVenda as numeric(16,2)),0) as VlVenda,
COALESCE(cast(c.VlVendaMin as numeric(16,2)),0) as VlVendaMin,
COALESCE(cast(c.VlCtoUltComp as numeric(16,2)),0) as VlCtoUltComp,
COALESCE(cast(c.VlPromocional as numeric(16,2)),0) as VlPromocional,
