    CODPROD,
    CODPLAN,
    DSSIMULACAO,
    DTCADASTRO,
    SITUACAO,
    DESCPROD,
    PRTOTAL,
    PRLUCRO,
    VLSERVICO,
    VLCUSTO,
    VLBASE,
    VLLUCRO,
    VLFATOR,
