cast(coalesce(f.prtotal,0) as numeric(10,3))    as prtotal,
cast(coalesce(f.prlucro,0) as numeric(10,3))    as prlucro,
cast(coalesce(f.vlservico,0) as numeric(14,4))  as vlservico,
