cast(coalesce(f.vlpreco,0) as numeric(14,4))    as vlpreco,
cast(coalesce(f.vlbasefixo,0) as numeric(14,4)) as vlbasefixo,
cast(coalesce(f.vlcustoliq,0) as numeric(14,4)) as vlcustoliq
From PRD_SIMULAPRECOC F
Left Join V_PRD_PRDVL C on c.codprod=f.codprod
;



/* View: V_PRD_SIMULAPRECOMP */
CREATE VIEW V_PRD_SIMULAPRECOMP(
    CDSIMULACAO,
    CODPROD,
    NRSEQUENCIA,
    CODMP,
    DESCRPROD,
    DESCRMP,
    USUARIO,
    DATAATU,
    HORAATU,
    MOEDACUSTOPA,
    MOEDACUSTOMP,
    NOMEMOEDACUSTOPA,
    NOMEMOEDACUSTOMP,
    QTCONSUMO,
    QTSALDOPA,
    QTSALDOMP,
    VLCUSTOPA,
    VLCUSTOMP,
    VLUNITARIO,
    VLTOTAL)
AS
Select
e.CdSimulacao,
e.CodProd,
e.NrSequencia,
e.CodMp,
d.DescCompleta as DescrProd,
f.DescCompleta as DescrMP,
e.usuario,
e.dataatu,
e.horaatu,
d.moedacompra as MoedaCustoPA,
f.moedacompra as MoedaCustoMP,
d.nomemoeda   as NomeMoedaCustoPA,
f.nomemoeda   as NomeMoedaCustoMP,
COALESCE(cast(e.QtConsumo    as numeric(10,3)),0) as QtConsumo,
COALESCE(cast(d.QtFisica     as numeric(10,3)),0) as QtSaldoPA,
COALESCE(cast(f.QtFisica     as numeric(10,3)),0) as QtSaldoMP,
COALESCE(cast(d.VlCtoUltComp as numeric(14,3)),0) as vlCustoPA,
COALESCE(cast(f.VlCtoUltComp as numeric(14,3)),0) as vlCustoMP,
COALESCE(cast(e.vlunitario   as numeric(14,3)),0) as VlUnitario,
COALESCE(cast(e.vltotal      as numeric(14,3)),0) as VlTotal
From PRD_SIMULAPRECOMP E
left Join V_PRD_PRDQTVL D on d.codprod =e.codprod
left Join V_PRD_PRDQTVL F on f.codprod =e.codmp
;



