/* View: V_PRD_VEICULO */
CREATE VIEW V_PRD_VEICULO(
    CODGRU,
    CODSUB,
    CODITEM1,
    CODITEM2,
    CODPROD,
    DESCITEM2,
    DESCRICAO,
    DESCCOMPLETA,
    UNIDMEDIDA,
    CST,
    NCM,
    PESO,
    IMPOSTO,
    CODBAR,
    INFOADIC,
    CODCOR,
    DSCOR,
    CODMARCA,
    DSMARCA,
    DSTIPOMARCA,
    CODMODELO,
    DSMODELO,
    DSTIPOMODELO,
    DSCHASSI,
    KMATUAL,
    KMFINAL,
    DATATROCA,
    INFILTRONOVO,
    ANOFABR,
    TPVEICULO,
    ANOMODELO,
    TPCOMBUSTIVEL,
    DSCOMBUSTIVEL,
    PLACAVEICULO,
    USUARIOINC,
    DATAINC,
    USUARIO,
    DATAATU,
    HORAATU,
    NIVELG,
    DESCRICAOGRU,
    DESCCOMPLETAGRU,
    NIVELS,
    DESCRICAOSUB,
    DESCCOMPLETASUB,
    NIVELI,
    CODGRUSUB,
    CODGRUSUBITEM,
    QTFISICA,
    QTEMPENHADA,
    QTRESERVA,
    QTVENDIDA,
    QTRMA,
    QTTERCEIRO,
    VLVENDA,
    VLVENDAMIN,
    VLVENDAMAX,
    VLCTOULTCOMP,
    VLPROMOCIONAL,
    VLVENDAATACADO)
AS
select
p.CodGru,
p.CodSub,
p.CodItem1,
p.CodItem2,
p.CodProd,
p.DescItem2,
p.Descricao,
p.DescCompleta,
p.UnidMedida,
p.CST,
p.NCM,
p.Peso,
p.Imposto,
p.CodBar,
p.InfoAdic,
p.codcor,
h.descricao as dscor,
p.codmarca,
j.descricao as dsmarca,
j.tipo as dstipomarca,
p.codmodelo,
k.descricao as dsmodelo,
k.tipo as dstipomodelo,
p.dschassi,
p.kmatual,
p.kmfinal,
p.datatroca,
p.infiltronovo,
p.anofabr,
p.tpveiculo,
p.anomodelo,
p.tpcombustivel,
l.descricao as dscombustivel,
p.placaveiculo,
p.UsuarioInc,
p.DataInc,
p.Usuario,
p.DataAtu,
p.HoraAtu,
g.Descnivel as NivelG,
g.Descricao as DescricaoGru,
g.DescCompleta as DescCompletaGru,
s.Descnivel as NivelS,
s.Descricao as DescricaoSub,
s.DescCompleta as DescCompletaSub,
i.Descnivel as NivelI,
(p.CodGru || '.' || p.CodSub) as CodGruSub,
(p.CodGru || '.' || p.CodSub || '.' || p.CodItem1 || '.' || p.CodItem2) as CodGruSubItem,
COALESCE(m.QtFisica,0)       as QtFisica,
COALESCE(m.QtEmpenhada,0)    as QtEmpenhada,
COALESCE(m.QtReserva,0)      as QtReserva,
COALESCE(m.QtVendida,0)      as QtVendida,
COALESCE(m.QtRma,0)          as QtRma,
COALESCE(m.QtTerceiro,0)     as QtTerceiro,
COALESCE(n.VlVenda,0)        as VlVenda,
COALESCE(n.VlVendaMin,0)     as VlVendaMin,
COALESCE(n.VlVendaMax,0)     as VlVendaMax,
COALESCE(n.VlCtoUltComp,0)   as VlCtoUltComp,
COALESCE(n.VlPromocional,0)  as VlPromocional,
COALESCE(n.VlVendaAtacado,0) as VlVendaAtacado
From PRD_PRODUTO P
Left Join PRD_GRUPO G       on g.codgru=p.codgru
Left Join PRD_COR   H       on h.codcor=p.codcor
Left Join PRD_MARCA J       on j.codmarca=p.codmarca
Left Join PRD_MODELO K      on k.codmarca=p.codmarca
                           and k.codmodelo=p.codmodelo
Left Join TIP_COMBUSTIVEL L on l.tpcombustivel=p.tpcombustivel
Left Join PRD_QTDE  M       on m.codprod=p.codprod
Left Join PRD_VALOR N       on n.codprod=p.codprod
Left Join PRD_SUBGRUPO S    on s.codgru=p.codgru and s.codsub=p.codsub
Left Join PRD_ITEM1 I       on i.coditem1=p.coditem1
;



/* View: V_RHU_FUNCIONARIO */
CREATE VIEW V_RHU_FUNCIONARIO(
    CODEMP,
    NRMATRICULA,
    CODFUNC,
    DSFUNC,
    CODVEND,
    NOMEVEND,
    NRTURNO,
    DSTURNO,
    QTBATIDA,
    BATIDAS1,
    HRTOLERANCIA,
    HRCARENCIA,
    QTHRDIARIA,
    TPSITUACAO,
    QTHRSSEMANA,
    QTHRSMES,
    DTADMISSAO,
    DTREGISTRO,
    DTTRANSF,
    DTAVISOINI,
    QTDIASAVISO,
    QTDIAEXPERIENCIA,
    DSFUNCAO,
    USUARIO,
    DATAATU,
    HORAATU,
    VLSALARIO)
AS
select
m.codemp,
m.NrMatricula,
m.CodCliente as Codfunc,
p.nome as dsfunc,
m.codvend,
v.nomevend,
m.nrturno,
s.descricao as dsturno,
s.qtbatida,
(s.hrini1 || ' ' || s.hrini2 || ' ' || s.hrfim1 || ' ' || s.hrfim2) as batidas1,
s.hrtolerancia,
s.hrcarencia,
s.qthrdiaria,
m.tpsituacao,
m.qthrssemana,
m.qthrsmes,
m.dtadmissao,
m.dtregistro,
m.dttransf,
m.dtavisoini,
m.qtdiasaviso,
m.qtdiaexperiencia,
m.dsfuncao,
m.Usuario,
m.DataAtu,
m.HoraAtu,
COALESCE(m.vlsalario,0) as vlsalario
From RHU_FUNCIONARIO m
Left Join CAD_CLIENTE   p on p.codcliente=m.codcliente
Left Join CAD_VEND      v on v.codvend   =m.codvend
Left Join RHU_TURNO     s on s.nrturno   =m.nrturno
;



/* View: V_RHU_MOVFOLHA */
CREATE VIEW V_RHU_MOVFOLHA(
    CODEMP,
    DTCOMPETENCIA,
    NRSEQMOVC,
    NRSEQMOVM,
    NRMATRICULA,
    NREVENTO,
    NRREGRA,
    DESCEVENTO,
    DTBASE,
    TPSITUACAO,
    TPFOLHA,
    CODMOEDA,
    TPPGTO,
    DTPGTO,
    DTINICIOFER,
    DTFIMFER,
    QTDEPENDENTE,
    DSFUNC,
    TPSITFUNC,
    DTADMISSAO,
    CODCLIENTE,
    CODVEND,
    NOMEVEND,
    NRTURNO,
    DSTURNO,
    QTHRDIARIA,
    QTHORACRED,
    QTHORADEB,
    VLLANCAMENTO,
    TPVALOR,
    VLBASE)
AS
Select
d.codemp,
d.dtcompetencia,
d.nrseqmovc,
m.nrseqmovm,
m.NrMatricula,
m.NrEvento,
c.Nrregra,
j.desctip as descevento,
m.dtbase,
d.tpsituacao,
k.tpfolha,
k.codmoeda,
d.tppgto,
d.dtpgto,
d.dtiniciofer,
d.dtfimfer,
c.qtdependente,
p.nome as dsfunc,
c.tpsituacao as tpsitfunc,
c.dtadmissao,
c.codcliente,
c.codvend,
v.nomevend,
c.nrturno,
s.descricao as dsturno,
s.qthrdiaria,
m.qthoracred,
m.qthoradeb,
coalesce(m.vllancamento,0) as vllancamento,
j.tpevento as tpvalor,
coalesce(m.vlbase,0) as vlbase
from RHU_MOVC d
Left Join RHU_MOVI       m on  m.codemp        =d.codemp
                           and m.dtcompetencia =d.dtcompetencia
                           and m.nrseqmovc     =d.nrseqmovc
Left Join RHU_FUNCIONARIO c on c.nrmatricula   =m.nrmatricula
Left Join CAD_CLIENTE     p on p.codcliente    =c.codcliente
Left Join CAD_VEND        v on v.codvend       =c.codvend
Left Join RHU_TURNO       s on s.nrturno       =c.nrturno
Left Join TIP_EVENTORHU   j on j.codtip        =m.nrevento
Left Join RHU_REGRAFOLHAC k on k.nrregra       =c.nrregra
;



/* View: V_RHU_MOVHORA */
CREATE VIEW V_RHU_MOVHORA(
    CODEMP,
    NRMATRICULA,
    DTMESANO,
    NUMLANCTO,
    NUMSEQ,
    DATALANCTO,
    HRENTPER1,
    HRSAIPER1,
    HRENTPER2,
    HRSAIPER2,
    HREXTRA50,
    HREXTRA100,
    HRNOTURNA,
    HRTOTNORMAL,
    HRTOTNEG,
    TPSITUACAO,
    DTENCERRAMENTO,
    DSFUNC,
    CODCLIENTE,
    CODVEND,
    NOMEVEND,
    NRTURNO,
    DSTURNO,
    QTBATIDA,
    HRTOLERANCIA,
    HRCARENCIA,
    QTHRDIARIA,
    TPSITFUNC,
    QTHRSSEMANA,
    QTHRSMES,
    DTADMISSAO,
    DTREGISTRO,
    DTTRANSF,
    DTAVISOINI,
    QTDIASAVISO,
    QTDIAEXPERIENCIA,
    USUARIO,
    DATAATU,
    HORAATU,
    VLSALARIO)
AS
Select
d.codemp,
d.NrMatricula,
d.dtmesano,
d.numlancto,
m.numseq,
m.datalancto,
m.hrentper1,
m.hrsaiper1,
m.hrentper2,
m.hrsaiper2,
m.hrextra50,
m.hrextra100,
m.hrnoturna,
m.hrtotnormal,
m.hrtotneg,
d.tpsituacao,
d.dtencerramento,
p.nome as dsfunc,
c.codcliente,
c.codvend,
v.nomevend,
c.nrturno,
s.descricao as dsturno,
s.qtbatida,
s.hrtolerancia,
s.hrcarencia,
s.qthrdiaria,
c.tpsituacao as tpsitfunc,
c.qthrssemana,
c.qthrsmes,
c.dtadmissao,
c.dtregistro,
c.dttransf,
c.dtavisoini,
c.qtdiasaviso,
c.qtdiaexperiencia,
m.Usuario,
m.DataAtu,
m.HoraAtu,
COALESCE(c.vlsalario,0) as vlsalario
From RHU_MOVHORAC d
Left Join RHU_MOVHORAI    m on m.codemp     =d.codemp
                           and m.nrmatricula=d.nrmatricula
                           and m.dtmesano   =d.dtmesano
                           and m.numlancto  =d.numlancto
Left Join RHU_FUNCIONARIO c on c.nrmatricula=d.nrmatricula
Left Join CAD_CLIENTE     p on p.codcliente =c.codcliente
Left Join CAD_VEND        v on v.codvend    =c.codvend
Left Join RHU_TURNO       s on s.nrturno    =c.nrturno
;



/* View: V_RHU_REGRAFOLHA */
CREATE VIEW V_RHU_REGRAFOLHA(
    NRREGRA,
    TPFOLHA,
    NRSEQITEM,
    DESCREGRA,
    DESCTIPFOLHA,
    NREVENTO,
    DESCEVENTO,
    CODMOEDA,
    TPCALCULO,
    PRALIQUOTA,
    VLCREDFIXO,
    VLDEBFIXO,
    USUARIO,
    DATAATU,
    HORAATU)
AS
select
m.nrregra,
m.tpfolha,
m.nrseqitem,
d.descregra,
p.desctip as desctipfolha,
m.nrevento,
c.desctip as descevento,
d.codmoeda,
m.tpcalculo,
COALESCE(m.praliquota,0) as praliquota,
COALESCE(m.vlcredfixo,0) as vlcredfixo,
COALESCE(m.vldebfixo,0)  as vldebfixo,
m.usuario,
m.dataatu,
m.horaatu
From RHU_REGRAFOLHA m
Left Join RHU_REGRAFOLHAC d on d.nrregra =m.nrregra
                           and d.tpfolha =m.tpfolha
Left Join TIP_EVENTORHU   c on c.codtip  =m.nrevento
Left Join TIP_FOLHARHU    p on p.codtip  =m.tpfolha
;




