SET TERM ^ ;

ALTER PROCEDURE SP_BUSCA_ULTIMA_SAIDA (
    PPRODUTO INTEGER)
RETURNS (
    CODPROD INTEGER,
    RULTDTMOV DATE)
AS
begin
     Select codprod,max(datamov) as datamov from mov_saii
     where codprod    = :pproduto and
           tp_situacao=4 and
           tpopermov in (1,23,20) group by codprod
     into
     :codprod,:rultdtmov;

     if (:rultdtmov is null) then
     begin
        select datainc from prd_produto where codprod=:codprod
        into
        :rultdtmov;
     end
     suspend;
end
^


SET TERM ; ^


